import type { RawQ } from "../types";
// Scholar tier (Mutaqaddim and ʿĀlim) qirāʾāt: differences of the Seven and the Ten at named verses, the rasm of the Uthmānic copies, transmitters, conditions of acceptance and the classical works. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  { id: "xqr-001", s: "qiraat", g: 4, d: 6, t: ["farsh", "seven-readers"], src: "al-Shāṭibī, Ḥirz al-Amānī, sūrat al-Fātiḥa; Ibn Mujāhid, Kitāb al-Sabʿa fī al-Qirāʾāt", v: "1:4", w: 1,
    en: ["Ḥafṣ reads the highlighted word with an alif (mālik). Which two of the Seven read it with the alif, the others reading it without (malik)?", ["ʿĀṣim and al-Kisāʾī", "Nāfiʿ and Ibn Kathīr", "Abū ʿAmr and Ibn ʿĀmir", "Ḥamza and Ibn ʿĀmir"], "Among the Seven only ʿĀṣim and al-Kisāʾī read it with the alif; Nāfiʿ, Ibn Kathīr, Abū ʿAmr, Ibn ʿĀmir and Ḥamza read it without. Yaʿqūb and Khalaf among the Ten follow the alif. Commentators note that both forms are attested names of God’s attributes: ‘owner’ (mālik) and ‘king’ (malik), and each is supported by other verses."],
    de: ["Ḥafṣ liest das markierte Wort mit Alif (mālik). Welche zwei der Sieben lesen es mit Alif, während die übrigen es ohne (malik) lesen?", ["ʿĀṣim und al-Kisāʾī", "Nāfiʿ und Ibn Kaṯīr", "Abū ʿAmr und Ibn ʿĀmir", "Ḥamza und Ibn ʿĀmir"], "Unter den Sieben lesen nur ʿĀṣim und al-Kisāʾī es mit Alif; Nāfiʿ, Ibn Kaṯīr, Abū ʿAmr, Ibn ʿĀmir und Ḥamza lesen es ohne. Von den Zehn folgen Yaʿqūb und Ḫalaf dem Alif. Die Kommentatoren halten fest, dass beide Formen bezeugte Namen göttlicher Eigenschaften sind: ‚Besitzer‘ (mālik) und ‚König‘ (malik), und beide werden durch andere Verse gestützt."],
    ar: ["يقرأ حفص الكلمة المظللة بالألف. فأي اثنين من القراء السبعة قرآ بالألف وقرأ الباقون بغير ألف؟", ["عاصم والكسائي", "نافع وابن كثير", "أبو عمرو وابن عامر", "حمزة وابن عامر"], "قرأ بالألف من السبعة عاصم والكسائي فقط، وقرأ نافع وابن كثير وأبو عمرو وابن عامر وحمزة بغير ألف، ووافق عاصمًا والكسائيَّ من العشرة يعقوب وخلف. والوجهان ثابتان يدلان على صفتين من صفات الله: الملك والمُلك، ولكل منهما شواهد من آيات أخرى."] },

  { id: "xqr-002", s: "qiraat", g: 4, d: 6, t: ["farsh", "seven-readers"], src: "al-Dānī, al-Taysīr fī al-Qirāʾāt al-Sabʿ; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Baqara", v: "2:85", w: 11,
    en: ["Ḥafṣ reads the highlighted word with a single ẓāʾ (taẓāharūna). Which three of the Seven read it this way, whereas the rest double the ẓāʾ (taẓẓāharūna)?", ["ʿĀṣim, Ḥamza and al-Kisāʾī", "Nāfiʿ, Ibn Kathīr and Abū ʿAmr", "Ibn ʿĀmir, Ḥamza and al-Kisāʾī", "Nāfiʿ, ʿĀṣim and Abū ʿAmr"], "The three Kūfan readers ʿĀṣim, Ḥamza and al-Kisāʾī read it with takhfīf, a single ẓāʾ; the readers of Madīna, Makka, Baṣra and Shām (Nāfiʿ, Ibn Kathīr, Abū ʿAmr, Ibn ʿĀmir) read with tashdīd. Both forms come from the verb meaning to support one another against someone, the doubled ẓāʾ being an assimilation of the tāʾ of the form VI."],
    de: ["Ḥafṣ liest das markierte Wort mit einem einfachen Ẓāʾ (taẓāharūna). Welche drei der Sieben lesen es so, während die übrigen das Ẓāʾ verdoppeln (taẓẓāharūna)?", ["ʿĀṣim, Ḥamza und al-Kisāʾī", "Nāfiʿ, Ibn Kaṯīr und Abū ʿAmr", "Ibn ʿĀmir, Ḥamza und al-Kisāʾī", "Nāfiʿ, ʿĀṣim und Abū ʿAmr"], "Die drei Kufaner ʿĀṣim, Ḥamza und al-Kisāʾī lesen es mit Taḫfīf, einem einfachen Ẓāʾ; die Leser von Medina, Mekka, Basra und Syrien (Nāfiʿ, Ibn Kaṯīr, Abū ʿAmr, Ibn ʿĀmir) lesen mit Tašdīd. Beide Formen stammen vom Verb für das gegenseitige Unterstützen gegen jemanden, das verdoppelte Ẓāʾ ist eine Assimilation des Tāʾ der sechsten Form."],
    ar: ["يقرأ حفص الكلمة المظللة بظاء واحدة مخففة. فأي ثلاثة من السبعة قرؤوا كذلك وشدّد الباقون الظاء؟", ["عاصم وحمزة والكسائي", "نافع وابن كثير وأبو عمرو", "ابن عامر وحمزة والكسائي", "نافع وعاصم وأبو عمرو"], "قرأ الكوفيون الثلاثة عاصم وحمزة والكسائي بالتخفيف، وقرأ أهل المدينة ومكة والبصرة والشام (نافع وابن كثير وأبو عمرو وابن عامر) بالتشديد، والفعل واحد من التظاهر وهو التعاون على الخصم، والتشديد إدغام لتاء التفاعل."] },

  { id: "xqr-003", s: "qiraat", g: 4, d: 7, t: ["farsh", "rasm"], src: "al-Dānī, al-Muqniʿ fī Maʿrifat Marsūm Maṣāḥif Ahl al-Amṣār; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Baqara", v: "2:132", w: 1,
    en: ["Ḥafṣ reads the highlighted word in the form with a doubled ṣād (waṣṣā). Which readers read the alternative wa-awṣā with a hamza, and which muṣḥafs are said to carry the alif in the rasm?", ["Nāfiʿ and Ibn ʿĀmir; the muṣḥafs of Madīna and Shām", "Ibn Kathīr and Abū ʿAmr; the muṣḥafs of Makka and Baṣra", "ʿĀṣim and Ḥamza; the muṣḥaf of Kūfa", "Al-Kisāʾī and Ibn ʿĀmir; the muṣḥaf of Shām only"], "Nāfiʿ and Ibn ʿĀmir (and Abū Jaʿfar) read awṣā, and the Madinan and Syrian copies write an alif in the word. The others read waṣṣā, in agreement with the other copies where the alif is not written. The case is a standard example of how a variant in the rasm correlates with readings from the same region."],
    de: ["Ḥafṣ liest das markierte Wort in der Form mit doppeltem Ṣād (waṣṣā). Welche Leser lesen die Alternative wa-awṣā mit Hamza, und in welchen Muṣḥafen soll das Alif im Rasm stehen?", ["Nāfiʿ und Ibn ʿĀmir; die Muṣḥafe von Medina und Syrien", "Ibn Kaṯīr und Abū ʿAmr; die Muṣḥafe von Mekka und Basra", "ʿĀṣim und Ḥamza; der Muṣḥaf von Kufa", "Al-Kisāʾī und Ibn ʿĀmir; nur der syrische Muṣḥaf"], "Nāfiʿ und Ibn ʿĀmir (und Abū Ǧaʿfar) lesen awṣā, und die medinensischen und syrischen Exemplare schreiben ein Alif im Wort. Die anderen lesen waṣṣā, in Übereinstimmung mit den anderen Exemplaren, in denen das Alif nicht geschrieben ist. Der Fall ist ein Standardbeispiel dafür, wie eine Variante im Rasm mit Lesarten derselben Region zusammenhängt."],
    ar: ["يقرأ حفص الكلمة المظللة بتضعيف الصاد. فمن قرأ الوجه الآخر بالهمزة والألف، وفي أي المصاحف يُروى أن الألف مرسومة فيها؟", ["نافع وابن عامر، وفي مصحفي المدينة والشام", "ابن كثير وأبو عمرو، وفي مصحفي مكة والبصرة", "عاصم وحمزة، وفي مصحف الكوفة", "الكسائي وابن عامر، وفي مصحف الشام وحده"], "قرأ نافع وابن عامر (وأبو جعفر) بالهمزة، ورُسمت الألف في المصحفين المدني والشامي، وقرأ الباقون بالتضعيف موافقةً للمصاحف الأخرى التي لا ألف فيها. وهي مثال معروف لارتباط اختلاف الرسم باختلاف القراءة بين الأمصار."] },

  { id: "xqr-004", s: "qiraat", g: 4, d: 6, t: ["farsh", "seven-readers"], src: "al-Dānī, al-Taysīr; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Baqara", v: "2:184", w: 18,
    en: ["Ḥafṣ reads ‘food of a poor person’ (ṭaʿāmu miskīnin), with the second word singular. Which two of the Seven read it as plural, masākīna?", ["Nāfiʿ and Ibn ʿĀmir", "Ibn Kathīr and Abū ʿAmr", "ʿĀṣim and Ḥamza", "Ḥamza and al-Kisāʾī"], "Nāfiʿ and Ibn ʿĀmir (with Abū Jaʿfar) read the second word as masākīna in the plural and the first word without tanwīn in an annexation, so the expiation is food of poor people for the days not fasted. The singular reading gives the sense of feeding one poor person for each day."],
    de: ["Ḥafṣ liest ‚Speise eines Armen‘ (ṭaʿāmu miskīnin), das zweite Wort im Singular. Welche zwei der Sieben lesen es im Plural masākīna?", ["Nāfiʿ und Ibn ʿĀmir", "Ibn Kaṯīr und Abū ʿAmr", "ʿĀṣim und Ḥamza", "Ḥamza und al-Kisāʾī"], "Nāfiʿ und Ibn ʿĀmir (mit Abū Ǧaʿfar) lesen das zweite Wort im Plural masākīna und das erste ohne Tanwīn in einer Genitivverbindung, sodass die Sühne in der Speise für Arme für die nicht gefasteten Tage besteht. Die Singularlesung gibt den Sinn, einen Armen für jeden Tag zu speisen."],
    ar: ["يقرأ حفص الكلمة التي بعد المظللة بالإفراد. فأي اثنين من السبعة قرآ بالجمع مع إضافة الكلمة المظللة إليها؟", ["نافع وابن عامر", "ابن كثير وأبو عمرو", "عاصم وحمزة", "حمزة والكسائي"], "قرأ نافع وابن عامر (ومعهما أبو جعفر) الكلمة الثانية جمعًا بلا تنوين في الأولى على الإضافة، والمعنى طعام مساكين عن الأيام المفطرة، وقراءة الإفراد بمعنى إطعام مسكين عن كل يوم."] },

  { id: "xqr-005", s: "qiraat", g: 4, d: 7, t: ["farsh", "fiqh-and-qiraat"], tr: ["comparative", "hanafi", "jumhur"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 2:222; Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra (chapter on menstruation); al-Shāṭibī, Ḥirz al-Amānī", v: "2:222", w: 14,
    en: ["Ḥafṣ reads the highlighted verb as yaṭhurna (‘they become clean’). Shuʿba, Ḥamza and al-Kisāʾī read yaṭṭahharna (‘they purify themselves’). Which statement correctly describes how the two readings figured in the legal discussion?", ["Most jurists required ghusl before intercourse, relying on the reading yaṭṭahharna and the following verb; the Ḥanafīs allowed it once bleeding ended at its maximum period, relying on yaṭhurna", "All schools agree that the two readings give different rulings that cannot be harmonised", "The Ḥanafīs required ghusl while the other schools did not", "The readings were not used in the legal discussion at all"], "The reading yaṭhurna means bleeding has stopped, and the continuation tataṭahharna means they have washed. The majority (Mālikīs, Shāfiʿīs, Ḥanbalīs) took the verse to require ghusl before intercourse, supported by the stronger form. The Ḥanafīs held that intercourse becomes lawful when the bleeding stops at the maximum period of ten days, even without ghusl. This is a classical case in which a qirāʾa variant is part of the discussion of the schools."],
    de: ["Ḥafṣ liest das markierte Verb als yaṭhurna (‚sie werden rein‘). Šuʿba, Ḥamza und al-Kisāʾī lesen yaṭṭahharna (‚sie reinigen sich‘). Welche Aussage beschreibt richtig, wie die beiden Lesarten in der rechtlichen Diskussion eine Rolle spielten?", ["Die meisten Juristen verlangten vor dem Verkehr die Ganzwaschung und stützten sich auf die Lesart yaṭṭahharna und das folgende Verb; die Hanafiten erlaubten ihn, wenn die Blutung am Höchstzeitraum endete, gestützt auf yaṭhurna", "Alle Schulen sind sich einig, dass die beiden Lesarten unterschiedliche Urteile ergeben, die sich nicht vereinen lassen", "Die Hanafiten verlangten die Ganzwaschung, die anderen Schulen nicht", "Die Lesarten spielten in der rechtlichen Diskussion überhaupt keine Rolle"], "Die Lesart yaṭhurna bedeutet, dass die Blutung aufgehört hat, die Fortsetzung tataṭahharna, dass sie sich gewaschen haben. Die Mehrheit (Malikiten, Schafiiten, Hanbaliten) verstand den Vers so, dass vor dem Verkehr die Ganzwaschung nötig ist, gestützt auf die stärkere Form. Die Hanafiten hielten den Verkehr für erlaubt, wenn die Blutung am Höchstzeitraum von zehn Tagen endet, auch ohne Ganzwaschung. Das ist ein klassischer Fall, in dem eine Lesartvariante Teil der Diskussion der Schulen ist."],
    ar: ["يقرأ حفص الفعل المظلل بتخفيف الطاء والهاء، وقرأه شعبة وحمزة والكسائي بتشديدهما. أي عبارة تصف دور القراءتين في الخلاف الفقهي؟", ["اشترط أكثر الفقهاء الغسل قبل الجماع اعتمادًا على قراءة التشديد والفعل التالي، وأجازه الحنفية إذا انقطع الدم لأكثر مدة الحيض اعتمادًا على قراءة التخفيف", "اتفقت المذاهب على أن القراءتين تعطيان حكمين متعارضين لا يمكن الجمع بينهما", "أوجب الحنفية الغسل ولم يوجبه غيرهم", "لم تُستعمل القراءتان في الخلاف الفقهي أصلًا"], "قراءة التخفيف بمعنى انقطاع الدم، والفعل التالي بمعنى الاغتسال. وذهب الجمهور من المالكية والشافعية والحنابلة إلى اشتراط الغسل قبل الوطء، وقال الحنفية يحل الوطء إذا انقطع الدم لأكثر الحيض وهو عشرة أيام ولو بلا غسل. وهي مثال كلاسيكي لدخول وجه قرائي في استدلال المذاهب."] },

  { id: "xqr-006", s: "qiraat", g: 4, d: 6, t: ["farsh", "seven-readers"], src: "al-Dānī, al-Taysīr; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat Āl ʿImrān", v: "3:19", w: 1,
    en: ["In 3:19 the highlighted particle is read inna (with kasra) by Ḥafṣ. Which of the Seven reads it as anna (with fatḥa)?", ["al-Kisāʾī", "Nāfiʿ", "Ibn ʿĀmir", "Ḥamza"], "Al-Kisāʾī reads anna l-dīna with fatḥa, making the clause a substitute (badal) for the preceding ‘annahu lā ilāha illā huwa’ in the previous verse, so that the content of God’s testimony includes the statement about the religion. The others read inna as a new sentence. The two readings give different grammar but compatible meaning."],
    de: ["In 3:19 liest Ḥafṣ die markierte Partikel als inna (mit Kasra). Wer von den Sieben liest anna (mit Fatḥa)?", ["Al-Kisāʾī", "Nāfiʿ", "Ibn ʿĀmir", "Ḥamza"], "Al-Kisāʾī liest anna d-dīna mit Fatḥa und macht den Satz zum Ersatz (Badal) für das vorangehende ‚annahu lā ilāha illā huwa‘ im vorigen Vers, sodass der Inhalt des göttlichen Zeugnisses auch die Aussage über die Religion umfasst. Die anderen lesen inna als neuen Satz. Die beiden Lesarten ergeben unterschiedliche Grammatik, aber vereinbaren Sinn."],
    ar: ["يقرأ حفص الأداة المظللة في آل عمران 19 بكسر الهمزة. فمن من السبعة قرأها بفتحها؟", ["الكسائي", "نافع", "ابن عامر", "حمزة"], "قرأ الكسائي بفتح الهمزة ويجعل الجملة بدلًا من الجملة التي قبلها في الآية السابقة، فيكون مضمون شهادة الله شاملًا لقوله في الدين، وقرأ الباقون بالكسر استئنافًا. فالنحو مختلف والمعنى متفق."] },

  { id: "xqr-007", s: "qiraat", g: 4, d: 7, t: ["farsh", "rasm"], src: "al-Dānī, al-Muqniʿ fī Maʿrifat Marsūm Maṣāḥif Ahl al-Amṣār", v: "3:133", w: 1,
    en: ["Ḥafṣ reads the highlighted word with a wāw at the beginning (wa-sāriʿū). Which two of the Seven read it without the wāw, in agreement with the rasm of which copies?", ["Nāfiʿ and Ibn ʿĀmir; the Madinan and Syrian copies", "Ibn Kathīr and Abū ʿAmr; the Meccan and Basran copies", "ʿĀṣim and al-Kisāʾī; the Kūfan copy", "Ḥamza and Abū ʿAmr; the Basran copy"], "Nāfiʿ and Ibn ʿĀmir read sāriʿū without a wāw, and the Madinan and Syrian copies lack the wāw in the rasm, while the other copies have it. The omission turns the clause into a direct command to hasten, instead of a command joined to the preceding sentence."],
    de: ["Ḥafṣ liest das markierte Wort mit einem Wāw am Anfang (wa-sāriʿū). Welche zwei der Sieben lesen es ohne Wāw, in Übereinstimmung mit dem Rasm welcher Exemplare?", ["Nāfiʿ und Ibn ʿĀmir; die medinensischen und syrischen Exemplare", "Ibn Kaṯīr und Abū ʿAmr; die mekkanischen und basrischen Exemplare", "ʿĀṣim und al-Kisāʾī; das Kufaner Exemplar", "Ḥamza und Abū ʿAmr; das basrische Exemplar"], "Nāfiʿ und Ibn ʿĀmir lesen sāriʿū ohne Wāw, und den medinensischen und syrischen Exemplaren fehlt das Wāw im Rasm, während die anderen Exemplare es haben. Das Weglassen macht den Satz zu einem unmittelbaren Befehl zur Eile, statt zu einem an den vorigen Satz angeschlossenen Befehl."],
    ar: ["يقرأ حفص الكلمة المظللة بواو في أولها. فأي اثنين من السبعة قرآ بحذف الواو موافقين رسم أي مصاحف؟", ["نافع وابن عامر، وفي مصحفي المدينة والشام", "ابن كثير وأبو عمرو، وفي مصحفي مكة والبصرة", "عاصم والكسائي، وفي مصحف الكوفة", "حمزة وأبو عمرو، وفي مصحف البصرة"], "قرأ نافع وابن عامر بلا واو، وليس في المصحفين المدني والشامي واو في الرسم، وفي غيرهما واو. ويجعل الحذف الجملة أمرًا مستأنفًا بالمسارعة بدل أن تكون معطوفة على ما قبلها."] },

  { id: "xqr-008", s: "qiraat", g: 4, d: 6, t: ["farsh", "meaning-differences"], src: "al-Dānī, al-Taysīr; Makkī ibn Abī Ṭālib, al-Kashf ʿan Wujūh al-Qirāʾāt", v: "3:146", w: 4,
    en: ["Ḥafṣ reads qātala (‘fought’). Nāfiʿ, Ibn Kathīr and Abū ʿAmr read qutila (‘was killed’). How does the meaning change?", ["With qātala, many devoted men fought together with the prophet; with qutila, many devoted men were killed fighting with him, yet the rest did not lose heart", "With qutila, the prophet alone is killed; with qātala, he fights alone", "The two readings have exactly the same meaning", "With qātala the rabbānīs fled; with qutila they stayed"], "The verse praises steadfastness of the followers of earlier prophets. With qātala it says that many rabbānīs fought together with the prophet and did not weaken. With qutila (passive), on one analysis, it says that many were killed with him, and those who remained still did not weaken. The commentators note that both readings serve the point of the verse, which was revealed after Uḥud."],
    de: ["Ḥafṣ liest qātala (‚kämpfte‘). Nāfiʿ, Ibn Kaṯīr und Abū ʿAmr lesen qutila (‚wurde getötet‘). Wie ändert sich der Sinn?", ["Mit qātala kämpften viele Gottergebene gemeinsam mit dem Propheten; mit qutila wurden viele Gottergebene im Kampf mit ihm getötet, doch die übrigen verzagten nicht", "Mit qutila wird nur der Prophet getötet; mit qātala kämpft er allein", "Die beiden Lesarten haben genau denselben Sinn", "Mit qātala flohen die Rabbānīs; mit qutila blieben sie"], "Der Vers lobt die Standhaftigkeit der Anhänger früherer Propheten. Mit qātala besagt er, viele Rabbānīs hätten gemeinsam mit dem Propheten gekämpft und seien nicht schwach geworden. Mit qutila (Passiv) besagt er, nach einer Analyse, viele seien mit ihm getötet worden, und die Übrigen seien dennoch nicht schwach geworden. Die Kommentatoren halten fest, dass beide Lesarten dem Anliegen des Verses dienen, der nach Uḥud offenbart wurde."],
    ar: ["يقرأ حفص الفعل المظلل مبنيًّا للمعلوم، وقرأه نافع وابن كثير وأبو عمرو مبنيًّا للمجهول. كيف يتغير المعنى؟", ["على المبني للمعلوم قاتل كثير من الربيين مع النبي، وعلى المبني للمجهول قُتل كثير منهم معه ومع ذلك لم يهن الباقون", "على المبني للمجهول يُقتل النبي وحده وعلى المبني للمعلوم يقاتل وحده", "لا فرق في المعنى بين القراءتين", "على المبني للمعلوم فرّ الربيون وعلى المبني للمجهول ثبتوا"], "تمدح الآية ثبات أتباع الأنبياء السابقين، فعلى القراءة الأولى قاتل مع النبي ربيّون كثير فما ضعفوا، وعلى البناء للمجهول (وفق أحد التخريجين) قُتل معه كثير وبقي غيرهم لم يضعفوا. ويرى المفسرون أن القراءتين تخدمان غرض الآية التي نزلت بعد أحد."] },

  { id: "xqr-009", s: "qiraat", g: 4, d: 7, t: ["farsh", "nahw-and-qiraat"], tr: ["comparative"], src: "Sībawayh, al-Kitāb, on the coordination to a pronoun in the genitive; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Nisāʾ; Ibn Hishām, Mughnī al-Labīb", v: "4:1", w: 23,
    en: ["Ḥafṣ reads the highlighted word in the accusative (wa-l-arḥāma). Which of the Seven reads it as genitive (wa-l-arḥāmi), and what was the grammatical objection of the Basrans?", ["Ḥamza; the objection was that a noun cannot be joined to an attached pronoun in the genitive without repeating the preposition", "Nāfiʿ; the objection was that the word has no case ending", "Ibn Kathīr; the objection was that it must be nominative", "Abū ʿAmr; the objection was that it is a diptote"], "Ḥamza reads the genitive, joining the word to the pronoun in ‘by whom you ask one another’, and the Basrans held that coordination to an attached genitive pronoun requires repeating the preposition, so they called the reading weak. The Kufans permitted it, and defenders cite the authority of the reading and examples from poetry. Ḥafṣ’s accusative is joined to the name of God (‘fear God … and the wombs’), meaning to respect kinship ties."],
    de: ["Ḥafṣ liest das markierte Wort im Akkusativ (wa-l-arḥāma). Wer von den Sieben liest es im Genitiv (wa-l-arḥāmi), und was war der grammatische Einwand der Basrer?", ["Ḥamza; der Einwand war, dass ein Nomen nicht an ein angehängtes Pronomen im Genitiv angeschlossen werden kann, ohne die Präposition zu wiederholen", "Nāfiʿ; der Einwand war, dass das Wort keine Kasusendung hat", "Ibn Kaṯīr; der Einwand war, dass es Nominativ sein muss", "Abū ʿAmr; der Einwand war, dass es ein Diptotum ist"], "Ḥamza liest den Genitiv und verbindet das Wort mit dem Pronomen in ‚durch den ihr einander fragt‘; die Basrer meinten, die Koordination mit einem angehängten Genitivpronomen verlange die Wiederholung der Präposition, und nannten die Lesart schwach. Die Kufaner erlaubten sie, und Verteidiger verweisen auf die Autorität der Lesart und auf Beispiele aus der Dichtung. Der Akkusativ bei Ḥafṣ ist an den Gottesnamen angeschlossen (‚fürchtet Gott … und die Mutterleiber‘) und meint die Achtung der Verwandtschaftsbande."],
    ar: ["يقرأ حفص الكلمة المظللة بالنصب. فمن من السبعة قرأها بالجر وما اعتراض البصريين النحوي؟", ["حمزة، وكان الاعتراض أنه لا يُعطف على الضمير المجرور المتصل دون إعادة الجار", "نافع، وكان الاعتراض أن الكلمة بلا علامة إعراب", "ابن كثير، وكان الاعتراض أنها يجب أن تكون مرفوعة", "أبو عمرو، وكان الاعتراض أنها ممنوعة من الصرف"], "قرأ حمزة بالجر عطفًا على الضمير المجرور في الفعل السابق، ورأى البصريون أن العطف على الضمير المجرور المتصل يحتاج إلى إعادة الجار فضعّفوا القراءة، وأجازه الكوفيون واحتج المدافعون بثبوت القراءة وبشواهد من الشعر. أما نصب حفص فعطف على لفظ الجلالة، والمعنى اتقوا الله واتقوا قطيعة الأرحام."] },

  { id: "xqr-010", s: "qiraat", g: 4, d: 6, t: ["farsh", "fiqh-and-qiraat"], src: "al-Dānī, al-Taysīr; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Māʾida", v: "5:6", w: 15,
    en: ["Ḥafṣ reads the highlighted word in the accusative (arjulakum). Which of the Seven read it in the genitive (arjulikum)?", ["Ibn Kathīr, Abū ʿAmr, Ḥamza and Shuʿba ʿan ʿĀṣim", "Nāfiʿ, Ibn ʿĀmir, al-Kisāʾī and Ḥafṣ", "Nāfiʿ, Ibn Kathīr and al-Kisāʾī", "Ibn ʿĀmir, Ḥamza and Abū ʿAmr"], "The accusative (Nāfiʿ, Ibn ʿĀmir, al-Kisāʾī and Ḥafṣ) joins ‘your feet’ to ‘your faces and hands’, which are washed. The genitive (Ibn Kathīr, Abū ʿAmr, Ḥamza and Shuʿba) joins it to ‘your heads’, which are wiped. In the case of Ḥafṣ the washing is therefore explicit; the genitive reading is explained by the majority as the genitive of proximity, or as referring to the wiping over the khuffs."],
    de: ["Ḥafṣ liest das markierte Wort im Akkusativ (arjulakum). Wer von den Sieben liest es im Genitiv (arjulikum)?", ["Ibn Kaṯīr, Abū ʿAmr, Ḥamza und Šuʿba ʿan ʿĀṣim", "Nāfiʿ, Ibn ʿĀmir, al-Kisāʾī und Ḥafṣ", "Nāfiʿ, Ibn Kaṯīr und al-Kisāʾī", "Ibn ʿĀmir, Ḥamza und Abū ʿAmr"], "Der Akkusativ (Nāfiʿ, Ibn ʿĀmir, al-Kisāʾī und Ḥafṣ) schließt ‚eure Füße‘ an ‚eure Gesichter und Hände‘ an, die gewaschen werden. Der Genitiv (Ibn Kaṯīr, Abū ʿAmr, Ḥamza und Šuʿba) schließt es an ‚eure Köpfe‘ an, die bestrichen werden. Bei Ḥafṣ ist das Waschen also ausdrücklich; die Genitivlesart erklärt die Mehrheit als Genitiv der Nachbarschaft oder mit Bezug auf das Bestreichen der Ledersocken."],
    ar: ["يقرأ حفص الكلمة المظللة بالنصب. فمن من القراء السبعة قرأها بالجر؟", ["ابن كثير وأبو عمرو وحمزة وشعبة عن عاصم", "نافع وابن عامر والكسائي وحفص", "نافع وابن كثير والكسائي", "ابن عامر وحمزة وأبو عمرو"], "النصب (نافع وابن عامر والكسائي وحفص) عطف على الوجوه والأيدي المغسولة، والجر (ابن كثير وأبو عمرو وحمزة وشعبة) عطف على الرؤوس الممسوحة. فرواية حفص صريحة في الغسل، وتأولها الجمهور في قراءة الجر على الجر بالجوار أو على المسح على الخفين."] },

  { id: "xqr-011", s: "qiraat", g: 4, d: 7, t: ["farsh", "fiqh-and-qiraat"], tr: ["comparative", "jumhur"], src: "al-Ṭabarī, Jāmiʿ al-Bayān, on 5:6; al-Qurṭubī, al-Jāmiʿ li-Aḥkām al-Qurʾān; Ibn Rushd, Bidāyat al-Mujtahid", v: "5:6", w: 15,
    en: ["How did the majority of jurists deal with the genitive reading of the feet in the wuḍūʾ verse?", ["They held that the feet must be washed, explaining the genitive as one of proximity (jarr al-jiwār) or as referring to wiping over the khuffs, and they relied on the reports of washing", "They concluded that the feet need only be wiped, in every case", "They rejected the genitive reading as invalid", "They held that the feet need not be washed or wiped at all"], "The reading arjulikum can be read as coordinated with the wiped heads, which some early authorities, such as Ibn ʿAbbās in one report, understood as wiping. The majority of jurists reconcile the readings by washing, for the Prophet is reported to have washed his feet and to have said ‘woe to the heels from the fire’. They said the genitive is by adjacency or indicates wiping on khuffs, which the Sunna permits."],
    de: ["Wie gingen die meisten Juristen mit der Genitivlesart der Füße im Wuḍūʾ-Vers um?", ["Sie hielten daran fest, dass die Füße zu waschen sind, und erklärten den Genitiv als Genitiv der Nachbarschaft oder als Verweis auf das Bestreichen der Ledersocken, gestützt auf die Berichte vom Waschen", "Sie folgerten, die Füße seien in jedem Fall nur zu bestreichen", "Sie verwarfen die Genitivlesart als ungültig", "Sie hielten es für unnötig, die Füße zu waschen oder zu bestreichen"], "Die Lesart arjulikum kann als mit den bestrichenen Köpfen koordiniert gelesen werden, was manche frühe Autoritäten, etwa Ibn ʿAbbās in einem Bericht, als Bestreichen verstanden. Die Mehrheit der Juristen vereint die Lesarten durch das Waschen, denn vom Propheten wird berichtet, dass er seine Füße wusch und sagte ‚wehe den Fersen vom Feuer‘. Sie sagten, der Genitiv sei durch Nachbarschaft oder weise auf das Bestreichen der Ledersocken hin, das die Sunna erlaubt."],
    ar: ["كيف تعامل جمهور الفقهاء مع قراءة الجر في الأرجل في آية الوضوء؟", ["قالوا بوجوب غسل الرجلين وحملوا الجر على الجر بالجوار أو على المسح على الخفين، واعتمدوا على أخبار الغسل", "رأوا أن الرجلين تُمسحان فقط في كل حال", "ردّوا قراءة الجر بوصفها غير صحيحة", "رأوا أنه لا يجب غسل الرجلين ولا مسحهما"], "تُحمل قراءة الجر على العطف على الرؤوس الممسوحة، وفهم بعض المتقدمين كابن عباس في رواية منها المسح. ووفّق الجمهور بين القراءتين بالغسل لثبوت أنه ﷺ غسل رجليه وتوعّد العقب من النار، وقالوا إن الجر بالجوار أو يفيد المسح على الخفين الذي أجازته السنة."] },

  { id: "xqr-012", s: "qiraat", g: 4, d: 7, t: ["farsh", "rasm"], src: "al-Dānī, al-Muqniʿ fī Maʿrifat Marsūm Maṣāḥif Ahl al-Amṣār; al-Dānī, al-Taysīr", v: "6:57", w: 18,
    en: ["The word is written in the rasm without a final yāʾ and is read by Ḥafṣ as yaquṣṣu (‘narrates’). Which readers read it as yaqḍī (‘decides’), and what does this show?", ["Abū ʿAmr, Ibn ʿĀmir, Ḥamza and al-Kisāʾī; the rasm without a final letter allows both forms", "Nāfiʿ and Ibn Kathīr; the rasm requires only yaquṣṣu", "ʿĀṣim alone; the rasm has a yāʾ", "None of the Seven; yaqḍī is a shādhdh reading"], "Nāfiʿ, Ibn Kathīr and ʿĀṣim read yaquṣṣu, while Abū ʿAmr, Ibn ʿĀmir, Ḥamza and al-Kisāʾī read yaqḍī bi-l-ḥaqq. The reading of both forms is possible because the Uthmānic rasm omits the final letter (it is one form for both). It is a classical example of a rasm that supports two mutawātir readings."],
    de: ["Das Wort ist im Rasm ohne Endungs-Yāʾ geschrieben und wird von Ḥafṣ als yaquṣṣu (‚erzählt‘) gelesen. Wer liest es als yaqḍī (‚entscheidet‘), und was zeigt das?", ["Abū ʿAmr, Ibn ʿĀmir, Ḥamza und al-Kisāʾī; der Rasm ohne Endbuchstaben lässt beide Formen zu", "Nāfiʿ und Ibn Kaṯīr; der Rasm verlangt nur yaquṣṣu", "ʿĀṣim allein; der Rasm hat ein Yāʾ", "Keiner der Sieben; yaqḍī ist eine šāḏḏ-Lesart"], "Nāfiʿ, Ibn Kaṯīr und ʿĀṣim lesen yaquṣṣu, während Abū ʿAmr, Ibn ʿĀmir, Ḥamza und al-Kisāʾī yaqḍī bi-l-ḥaqq lesen. Beide Formen sind möglich, weil der uṯmānische Rasm den Endbuchstaben ausläßt (eine Form für beide). Es ist ein klassisches Beispiel für einen Rasm, der zwei mutawātir-Lesarten trägt."],
    ar: ["الكلمة المظللة مرسومة بلا ياء في آخرها ويقرؤها حفص من القص بمعنى الحكاية. فمن قرأها من القضاء بمعنى الحكم وما الذي يدل عليه ذلك؟", ["أبو عمرو وابن عامر وحمزة والكسائي، والرسم بلا ياء أخيرة يحتمل الوجهين", "نافع وابن كثير، والرسم لا يحتمل إلا الأولى", "عاصم وحده، والرسم فيه ياء", "لا أحد من السبعة، فالثانية شاذة"], "قرأ نافع وابن كثير وعاصم من القص وقرأ أبو عمرو وابن عامر وحمزة والكسائي من القضاء، ويصح الوجهان لأن الرسم العثماني حذف الحرف الأخير فاحتمل الصورتين. وهو مثال معروف لرسم يوافق قراءتين متواترتين."] },

  { id: "xqr-013", s: "qiraat", g: 4, d: 6, t: ["farsh", "seven-readers"], src: "al-Dānī, al-Taysīr; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Anʿām", v: "6:114", w: 16,
    en: ["Ḥafṣ reads the highlighted word with shadda (munazzalun). Which of the Seven read it with the shadda too, whereas the others read munzalun?", ["Ibn ʿĀmir (and ʿĀṣim in the riwāya of Ḥafṣ)", "Nāfiʿ and Ibn Kathīr", "Abū ʿAmr and Ḥamza", "Al-Kisāʾī and Abū ʿAmr"], "Ibn ʿĀmir and Ḥafṣ ʿan ʿĀṣim read the intensive form munazzalun, with the sense of being sent down in stages; the other readers, including Shuʿba, read munzalun. The difference does not change the reference, since the Quran came down gradually and as a whole to the lowest heaven."],
    de: ["Ḥafṣ liest das markierte Wort mit Šadda (munazzalun). Wer von den Sieben liest es ebenfalls mit Šadda, während die übrigen munzalun lesen?", ["Ibn ʿĀmir (und ʿĀṣim in der Riwāya von Ḥafṣ)", "Nāfiʿ und Ibn Kaṯīr", "Abū ʿAmr und Ḥamza", "Al-Kisāʾī und Abū ʿAmr"], "Ibn ʿĀmir und Ḥafṣ ʿan ʿĀṣim lesen die Intensivform munazzalun mit dem Sinn des stufenweisen Herabgesandtwerdens; die anderen Leser, auch Šuʿba, lesen munzalun. Der Unterschied ändert den Bezug nicht, da der Koran schrittweise herabkam."],
    ar: ["يقرأ حفص الكلمة المظللة بالتشديد (منزَّل). فمن قرأ بالتشديد أيضًا وقرأ غيرهم بالتخفيف؟", ["ابن عامر (وعاصم في رواية حفص)", "نافع وابن كثير", "أبو عمرو وحمزة", "الكسائي وأبو عمرو"], "قرأ ابن عامر وحفص عن عاصم بصيغة التكثير (منزَّل) بمعنى النزول مفرَّقًا، وقرأ الباقون ومنهم شعبة بالتخفيف، ولا يتغير المرجع لأن القرآن نزل منجَّمًا."] },

  { id: "xqr-014", s: "qiraat", g: 4, d: 7, t: ["farsh", "rasm"], src: "al-Dānī, al-Muqniʿ fī Maʿrifat Marsūm Maṣāḥif Ahl al-Amṣār; Abū ʿUbayd, Faḍāʾil al-Qurʾān", v: "9:100", w: 18,
    en: ["Ḥafṣ reads the highlighted word ‘beneath them’ without the preposition. Who reads it with the preposition (min taḥtihā), and which muṣḥaf has it written?", ["Ibn Kathīr; the Meccan muṣḥaf", "Nāfiʿ; the Madinan muṣḥaf", "Abū ʿAmr; the Basran muṣḥaf", "Ibn ʿĀmir; the Syrian muṣḥaf"], "Ibn Kathīr reads min taḥtihā with the preposition min, and the Meccan copy is reported to be the only one that has it written here. In all other places in the Quran, the expression has no min. The case is a standard proof that a reading follows the rasm of its region."],
    de: ["Ḥafṣ liest das markierte Wort ‚unter ihnen‘ ohne die Präposition. Wer liest es mit der Präposition (min taḥtihā), und welcher Muṣḥaf hat sie geschrieben?", ["Ibn Kaṯīr; der mekkanische Muṣḥaf", "Nāfiʿ; der medinensische Muṣḥaf", "Abū ʿAmr; der basrische Muṣḥaf", "Ibn ʿĀmir; der syrische Muṣḥaf"], "Ibn Kaṯīr liest min taḥtihā mit der Präposition min, und das mekkanische Exemplar soll das einzige sein, das sie hier geschrieben hat. An allen anderen Stellen im Koran hat der Ausdruck kein min. Der Fall ist ein Standardbeleg dafür, dass eine Lesart dem Rasm ihrer Region folgt."],
    ar: ["يقرأ حفص الكلمة المظللة، وهي ظرف المكان، بلا حرف جر قبلها. فمن قرأها بحرف الجر وفي أي مصحف رُسم؟", ["ابن كثير، وفي المصحف المكي", "نافع، وفي المصحف المدني", "أبو عمرو، وفي المصحف البصري", "ابن عامر، وفي المصحف الشامي"], "قرأ ابن كثير بزيادة حرف الجر، ويُذكر أن المصحف المكي هو الذي رُسم فيه هنا حرف الجر وحده، وفي سائر المواضع من القرآن لا يوجد، وهي حجة معروفة على أن القراءة تتبع رسم المصر."] },

  { id: "xqr-015", s: "qiraat", g: 4, d: 7, t: ["farsh", "rasm"], src: "al-Dānī, al-Muqniʿ fī Maʿrifat Marsūm Maṣāḥif Ahl al-Amṣār; al-Shāṭibī, Ḥirz al-Amānī", v: "9:107", w: 1,
    en: ["Ḥafṣ reads the highlighted word with a wāw at the start (wa-alladhīna). Who reads it without the wāw, and in agreement with which copies?", ["Nāfiʿ and Ibn ʿĀmir; the Madinan and Syrian copies", "Ibn Kathīr and Abū ʿAmr; the Meccan and Basran copies", "ʿĀṣim and Ḥamza; the Kūfan copy", "Al-Kisāʾī and Ḥamza; the Kūfan and Basran copies"], "Nāfiʿ and Ibn ʿĀmir read alladhīna ittakhadhū without the wāw, as in the Madinan and Syrian muṣḥafs, making the relative clause a description or a new sentence directly after the previous verse. The other readers have the wāw, as in the other copies, and read the clause as coordinated."],
    de: ["Ḥafṣ liest das markierte Wort mit einem Wāw am Anfang (wa-alladhīna). Wer liest es ohne Wāw, in Übereinstimmung mit welchen Exemplaren?", ["Nāfiʿ und Ibn ʿĀmir; die medinensischen und syrischen Exemplare", "Ibn Kaṯīr und Abū ʿAmr; die mekkanischen und basrischen Exemplare", "ʿĀṣim und Ḥamza; das Kufaner Exemplar", "Al-Kisāʾī und Ḥamza; die Kufaner und basrischen Exemplare"], "Nāfiʿ und Ibn ʿĀmir lesen alladhīna ittaḫaḏū ohne Wāw, wie in den medinensischen und syrischen Muṣḥafen, sodass der Relativsatz eine Beschreibung oder ein neuer Satz unmittelbar nach dem vorigen Vers ist. Die anderen Leser haben das Wāw, wie in den anderen Exemplaren, und lesen den Satz als angeschlossen."],
    ar: ["يقرأ حفص الكلمة المظللة بواو في أولها. فمن قرأها بحذف الواو وموافقًا أي مصاحف؟", ["نافع وابن عامر، وفي مصحفي المدينة والشام", "ابن كثير وأبو عمرو، وفي مصحفي مكة والبصرة", "عاصم وحمزة، وفي مصحف الكوفة", "الكسائي وحمزة، وفي مصحفي الكوفة والبصرة"], "قرأ نافع وابن عامر بحذف الواو موافقةً للمصحفين المدني والشامي فتكون الجملة الموصولة بدلًا أو استئنافًا بعد الآية السابقة، وقرأ الباقون بالواو موافقةً لبقية المصاحف على العطف."] },

  { id: "xqr-016", s: "qiraat", g: 4, d: 6, t: ["farsh", "meaning-differences"], src: "Makkī ibn Abī Ṭālib, al-Kashf ʿan Wujūh al-Qirāʾāt; al-Dānī, al-Taysīr", v: "10:2", w: 25,
    en: ["Ḥafṣ reads the highlighted word as la-sāḥirun (‘a magician’). Which of the Seven read la-siḥrun (‘magic’)?", ["Nāfiʿ, Abū ʿAmr and Ibn ʿĀmir", "Ibn Kathīr, ʿĀṣim and Ḥamza", "ʿĀṣim, Ḥamza and al-Kisāʾī", "Nāfiʿ, ʿĀṣim and al-Kisāʾī"], "The unbelievers speak of the Prophet in the first reading (la-sāḥirun, referring to the man) and of what he brings in the second (la-siḥrun, referring to the message). Nāfiʿ, Abū ʿAmr and Ibn ʿĀmir read siḥr, whereas Ibn Kathīr, ʿĀṣim, Ḥamza and al-Kisāʾī read sāḥir. Both are the kind of attribution unbelievers made, the one to the man and the other to the revelation."],
    de: ["Ḥafṣ liest das markierte Wort als la-sāḥirun (‚ein Zauberer‘). Wer von den Sieben liest la-siḥrun (‚Zauberei‘)?", ["Nāfiʿ, Abū ʿAmr und Ibn ʿĀmir", "Ibn Kaṯīr, ʿĀṣim und Ḥamza", "ʿĀṣim, Ḥamza und al-Kisāʾī", "Nāfiʿ, ʿĀṣim und al-Kisāʾī"], "Die Ungläubigen sprechen in der ersten Lesart (la-sāḥirun) vom Propheten, dem Mann, und in der zweiten (la-siḥrun) von dem, was er bringt, der Botschaft. Nāfiʿ, Abū ʿAmr und Ibn ʿĀmir lesen siḥr, während Ibn Kaṯīr, ʿĀṣim, Ḥamza und al-Kisāʾī sāḥir lesen. Beides ist die Art von Zuschreibung, die die Ungläubigen vornahmen, die eine an den Mann, die andere an die Offenbarung."],
    ar: ["يقرأ حفص الكلمة المظللة اسم فاعل أي وصفًا للرجل. فمن من السبعة قرأها مصدرًا (وصفًا لما جاء به)؟", ["نافع وأبو عمرو وابن عامر", "ابن كثير وعاصم وحمزة", "عاصم وحمزة والكسائي", "نافع وعاصم والكسائي"], "ينسب الكفار في القراءة الأولى السحر إلى الرجل بوصفه فاعله وفي الثانية إلى ما جاء به بوصفه مصدرًا، وقرأ نافع وأبو عمرو وابن عامر بالمصدر، وقرأ ابن كثير وعاصم وحمزة والكسائي باسم الفاعل، وكلاهما من نسبة الكفار، الأولى للنبي والثانية للوحي."] },

  { id: "xqr-017", s: "qiraat", g: 4, d: 6, t: ["farsh", "hamza"], src: "al-Dānī, al-Taysīr; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Kahf", v: "18:94", w: 5,
    en: ["Ḥafṣ reads the highlighted name with a hamza (yaʾjūj). Which of the Seven reads it with a hamza as he does?", ["ʿĀṣim alone; the others read yājūj without hamza", "Nāfiʿ and Ibn Kathīr", "Ḥamza and al-Kisāʾī", "Abū ʿAmr and Ibn ʿĀmir"], "ʿĀṣim alone among the Seven reads yaʾjūj and maʾjūj with hamza (in 18:94 and 21:96); the others read yājūj and mājūj, with a soft alif. Those who read with hamza derive the name from ajja (to blaze or rush); the others treat it as a foreign name pronounced with a soft alif."],
    de: ["Ḥafṣ liest den markierten Namen mit Hamza (yaʾǧūǧ). Wer von den Sieben liest ihn ebenfalls mit Hamza?", ["ʿĀṣim allein; die anderen lesen yāǧūǧ ohne Hamza", "Nāfiʿ und Ibn Kaṯīr", "Ḥamza und al-Kisāʾī", "Abū ʿAmr und Ibn ʿĀmir"], "Unter den Sieben liest nur ʿĀṣim yaʾǧūǧ und maʾǧūǧ mit Hamza (in 18:94 und 21:96); die anderen lesen yāǧūǧ und māǧūǧ mit weichem Alif. Wer mit Hamza liest, leitet den Namen von ajja (lodern, eilen) ab; die anderen behandeln ihn als Fremdnamen mit weichem Alif."],
    ar: ["يقرأ حفص الاسم المظلل بالهمز. فمن من السبعة قرأه بالهمز مثله؟", ["عاصم وحده، وقرأ الباقون بغير همز", "نافع وابن كثير", "حمزة والكسائي", "أبو عمرو وابن عامر"], "انفرد عاصم من السبعة بالهمز في «يأجوج ومأجوج» (الكهف 94 والأنبياء 96) وقرأ الباقون بالألف بلا همز، ومن همز اشتقه من أجَّ أي أسرع واضطرم، ومن لم يهمز عدّه اسمًا أعجميًّا."] },

  { id: "xqr-018", s: "qiraat", g: 4, d: 7, t: ["farsh", "riwaya-differences"], src: "al-Dānī, al-Taysīr; Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr", v: "19:19", w: 6,
    en: ["Ḥafṣ reads the highlighted verb li-ahaba (‘that I may give’). Which reader of the Seven, and which transmitter of another of them, read li-yahaba (‘that He may give’)?", ["Abū ʿAmr, and Warsh from Nāfiʿ", "Ibn Kathīr, and Qālūn from Nāfiʿ", "Ḥamza, and Shuʿba from ʿĀṣim", "Ibn ʿĀmir, and Hishām from him"], "In this verse the angel says ‘to give you a pure boy’. The reading li-ahaba has the angel as the giver by God’s command, and li-yahaba puts the giving directly on God. Abū ʿAmr and Warsh, with Yaʿqūb, read li-yahaba; Qālūn from Nāfiʿ reads li-ahaba. The case shows that two transmitters of the same reader may differ."],
    de: ["Ḥafṣ liest das markierte Verb li-ahaba (‚damit ich schenke‘). Welcher der Sieben und welcher Überlieferer eines anderen von ihnen lasen li-yahaba (‚damit er schenke‘)?", ["Abū ʿAmr und Warš von Nāfiʿ", "Ibn Kaṯīr und Qālūn von Nāfiʿ", "Ḥamza und Šuʿba von ʿĀṣim", "Ibn ʿĀmir und Hišām von ihm"], "In diesem Vers sagt der Engel ‚um einen reinen Knaben zu schenken‘. Die Lesart li-ahaba lässt den Engel auf Gottes Befehl als Schenkenden auftreten, li-yahaba legt das Schenken unmittelbar auf Gott. Abū ʿAmr und Warš lesen mit Yaʿqūb li-yahaba; Qālūn von Nāfiʿ liest li-ahaba. Der Fall zeigt, dass zwei Überlieferer desselben Lesers abweichen können."],
    ar: ["يقرأ حفص الفعل المظلل بهمزة المتكلم. فمن من السبعة، ومن راوي آخر منهم، قرأه بياء الغائب؟", ["أبو عمرو، وورش عن نافع", "ابن كثير، وقالون عن نافع", "حمزة، وشعبة عن عاصم", "ابن عامر، وهشام عنه"], "في الآية يقول الملك لمريم إنه رسول ربها ليهب لها غلامًا زكيًّا، فعلى همزة المتكلم يكون الواهب هو الملك بأمر الله، وعلى ياء الغائب تُسند الهبة إلى الله مباشرة. وقرأ بالياء أبو عمرو وورش ويعقوب، وقرأ قالون عن نافع بالهمزة، وهذا يبيّن أن راويين لقارئ واحد قد يختلفان."] },

  { id: "xqr-019", s: "qiraat", g: 4, d: 7, t: ["farsh", "nahw-and-qiraat"], src: "Ibn Khālawayh, al-Ḥujja fī al-Qirāʾāt al-Sabʿ; Makkī ibn Abī Ṭālib, al-Kashf ʿan Wujūh al-Qirāʾāt; al-Shāṭibī, Ḥirz al-Amānī", v: "20:63", w: 3,
    en: ["In 20:63 the highlighted word and the one before it have three readings among the Seven. Which statement is correct?", ["Abū ʿAmr reads inna hādhayni, Ibn Kathīr and Ḥafṣ read in hādhāni with a light in, and the others read inna hādhāni", "All the Seven read inna hādhāni", "Abū ʿAmr reads in hādhāni and Ibn Kathīr inna hādhayni", "Ḥafṣ reads inna hādhayni and the others in hādhāni"], "The text has a dual with alif where the particle inna would require the oblique ending. Abū ʿAmr reads the oblique form hādhayni to fit the grammar; Ibn Kathīr (who also doubles the nūn of the dual) and Ḥafṣ read the light in with the lām of the predicate separating it from the negation; the rest keep inna and explain the alif by the dialect that uses alif for all cases (Balḥārith ibn Kaʿb), or by a pronoun of the situation. It is a famous problem in the books of grammar."],
    de: ["In 20:63 gibt es für das markierte Wort und das davor unter den Sieben drei Lesarten. Welche Aussage ist richtig?", ["Abū ʿAmr liest inna hādhayni, Ibn Kaṯīr und Ḥafṣ lesen in hādhāni mit leichtem in, und die übrigen lesen inna hādhāni", "Alle Sieben lesen inna hādhāni", "Abū ʿAmr liest in hādhāni und Ibn Kaṯīr inna hādhayni", "Ḥafṣ liest inna hādhayni und die anderen in hādhāni"], "Der Text hat einen Dual mit Alif, wo die Partikel inna die Casus-obliquus-Endung verlangen würde. Abū ʿAmr liest die obliquen Form hādhayni, damit sie zur Grammatik passt; Ibn Kaṯīr (der auch das Nūn des Duals verdoppelt) und Ḥafṣ lesen das leichte in mit dem Lām des Prädikats, das es von der Verneinung unterscheidet; die übrigen behalten inna und erklären das Alif mit dem Dialekt, der in allen Fällen Alif verwendet (Balḥāriṯ ibn Kaʿb), oder mit einem Pronomen der Lage. Es ist ein berühmtes Problem der Grammatikbücher."],
    ar: ["في طه 63 للكلمة المظللة وما قبلها ثلاث قراءات عند السبعة. أي عبارة صحيحة؟", ["قرأ أبو عمرو بتشديد «إنّ» وياء المثنى، وقرأ ابن كثير وحفص بتخفيف «إنْ» مع ألف المثنى، وقرأ الباقون بتشديد «إنّ» وألف المثنى", "قرأ السبعة كلهم بتشديد «إنّ» وألف المثنى", "قرأ أبو عمرو بتخفيف «إنْ» وابن كثير بتشديدها مع الياء", "قرأ حفص بتشديد «إنّ» والياء وقرأ غيره بتخفيف «إنْ»"], "في النص مثنى بالألف حيث تقتضي «إنّ» صيغة النصب، فقرأ أبو عمرو بالياء موافقةً للقياس، وقرأ ابن كثير وحفص بتخفيف «إنْ» واللام الفارقة بينها وبين النافية، وأبقى الباقون «إنّ» وخرّجوا الألف على لغة من يلزم المثنى الألف في أحواله (بلحارث بن كعب) أو على ضمير الشأن. وهي مسألة مشهورة في كتب النحو."] },

  { id: "xqr-020", s: "qiraat", g: 4, d: 6, t: ["farsh", "nahw-and-qiraat"], src: "al-Dānī, al-Taysīr; al-Zamakhsharī, al-Kashshāf, on 27:22", v: "27:22", w: 12,
    en: ["Ḥafṣ reads the highlighted name with tanwīn (sabaʾin). Which two of the Seven read it without tanwīn, as a name that does not take it (sabaʾa)?", ["Ibn Kathīr and Abū ʿAmr", "Nāfiʿ and Ibn ʿĀmir", "Ḥamza and al-Kisāʾī", "ʿĀṣim and Nāfiʿ"], "Ibn Kathīr and Abū ʿAmr read sabaʾa with fatḥa and no tanwīn, taking it as the name of a city or a tribe that is a diptote; the others read it as a declinable name with tanwīn. The two forms agree on the reference to the people of Saba in Yemen, whom the hoopoe mentions."],
    de: ["Ḥafṣ liest den markierten Namen mit Tanwīn (sabaʾin). Welche zwei der Sieben lesen ihn ohne Tanwīn, als Namen, der es nicht nimmt (sabaʾa)?", ["Ibn Kaṯīr und Abū ʿAmr", "Nāfiʿ und Ibn ʿĀmir", "Ḥamza und al-Kisāʾī", "ʿĀṣim und Nāfiʿ"], "Ibn Kaṯīr und Abū ʿAmr lesen sabaʾa mit Fatḥa und ohne Tanwīn und nehmen es als Namen einer Stadt oder eines Stammes, der ein Diptotum ist; die anderen lesen es als deklinierbaren Namen mit Tanwīn. Beide Formen stimmen im Bezug auf das Volk von Saba im Jemen überein, das der Wiedehopf erwähnt."],
    ar: ["يقرأ حفص الاسم المظلل بالتنوين. فأي اثنين من السبعة قرآه بلا تنوين ممنوعًا من الصرف؟", ["ابن كثير وأبو عمرو", "نافع وابن عامر", "حمزة والكسائي", "عاصم ونافع"], "قرأ ابن كثير وأبو عمرو بالفتح بلا تنوين على أنه اسم مدينة أو قبيلة ممنوع من الصرف، وقرأ الباقون بالتنوين اسمًا منصرفًا، والمرجع واحد وهو أهل سبأ باليمن التي يذكرها الهدهد."] },

  { id: "xqr-021", s: "qiraat", g: 4, d: 6, t: ["farsh", "seven-readers"], src: "al-Dānī, al-Taysīr; al-Shāṭibī, Ḥirz al-Amānī, farsh sūrat al-Wāqiʿa", v: "56:75", w: 3,
    en: ["Ḥafṣ reads the highlighted word as a plural (mawāqiʿ). Which of the Seven read it as a singular (mawqiʿ)?", ["Ḥamza and al-Kisāʾī", "Nāfiʿ and Ibn Kathīr", "Abū ʿAmr and Ibn ʿĀmir", "ʿĀṣim and Abū ʿAmr"], "Ḥamza and al-Kisāʾī (with Khalaf) read the singular mawqiʿ, a verbal noun that covers the places or the setting of the stars; the others read the plural mawāqiʿ, the places where the stars set or the portions in which the Quran came down. Commentators mention both meanings for this oath."],
    de: ["Ḥafṣ liest das markierte Wort als Plural (mawāqiʿ). Wer von den Sieben liest es als Singular (mawqiʿ)?", ["Ḥamza und al-Kisāʾī", "Nāfiʿ und Ibn Kaṯīr", "Abū ʿAmr und Ibn ʿĀmir", "ʿĀṣim und Abū ʿAmr"], "Ḥamza und al-Kisāʾī (mit Ḫalaf) lesen den Singular mawqiʿ, ein Verbalnomen, das die Orte oder den Untergang der Sterne umfasst; die anderen lesen den Plural mawāqiʿ, die Orte, an denen die Sterne untergehen, oder die Abschnitte, in denen der Koran herabkam. Die Kommentatoren nennen beide Bedeutungen für diesen Schwur."],
    ar: ["يقرأ حفص الكلمة المظللة جمعًا. فمن من السبعة قرأها مفردًا؟", ["حمزة والكسائي", "نافع وابن كثير", "أبو عمرو وابن عامر", "عاصم وأبو عمرو"], "قرأ حمزة والكسائي (ومعهما خلف) بالإفراد على المصدر الشامل لمواضع النجوم أو غروبها، وقرأ الباقون بالجمع مواقع النجوم أي مغاربها أو مواضع نزول القرآن، ويذكر المفسرون المعنيين في هذا القسم."] },

  { id: "xqr-022", s: "qiraat", g: 4, d: 6, t: ["farsh", "meaning-differences"], src: "Makkī ibn Abī Ṭālib, al-Kashf ʿan Wujūh al-Qirāʾāt; al-Dānī, al-Taysīr", v: "81:24", w: 5,
    en: ["Ḥafṣ reads the highlighted word with ḍād (biḍanīn, ‘miserly’). Some of the Seven read it with ẓāʾ (bi-ẓanīn). Who are they, and what does the reading mean?", ["Ibn Kathīr, Abū ʿAmr and al-Kisāʾī; ‘suspected’ (of withholding the unseen)", "Nāfiʿ, Ibn ʿĀmir and Ḥamza; ‘miserly’", "ʿĀṣim and Ḥamza; ‘accused of lying’", "Ibn ʿĀmir and al-Kisāʾī; ‘absent’"], "Ibn Kathīr, Abū ʿAmr and al-Kisāʾī read bi-ẓanīn with the meaning ‘suspected or accused’; the Prophet is not accused regarding the unseen. The others read biḍanīn, ‘stingy’, so he does not withhold what was revealed to him. The two readings are compatible and are both attested defences of the Prophet."],
    de: ["Ḥafṣ liest das markierte Wort mit Ḍād (biḍanīn, ‚geizig‘). Einige der Sieben lesen es mit Ẓāʾ (bi-ẓanīn). Wer sind sie, und was bedeutet die Lesart?", ["Ibn Kaṯīr, Abū ʿAmr und al-Kisāʾī; ‚verdächtigt‘ (das Verborgene zurückzuhalten)", "Nāfiʿ, Ibn ʿĀmir und Ḥamza; ‚geizig‘", "ʿĀṣim und Ḥamza; ‚der Lüge beschuldigt‘", "Ibn ʿĀmir und al-Kisāʾī; ‚abwesend‘"], "Ibn Kaṯīr, Abū ʿAmr und al-Kisāʾī lesen bi-ẓanīn mit der Bedeutung ‚verdächtigt oder beschuldigt‘; der Prophet wird in Bezug auf das Verborgene nicht beschuldigt. Die anderen lesen biḍanīn, ‚knauserig‘, sodass er das ihm Offenbarte nicht zurückhält. Beide Lesarten sind vereinbar und beide bezeugte Verteidigungen des Propheten."],
    ar: ["يقرأ حفص الكلمة المظللة بالضاد، وقرأها بعض السبعة بالظاء. فمن هم وما معنى قراءتهم؟", ["ابن كثير وأبو عمرو والكسائي، وبمعنى المتَّهم في كتمان الغيب", "نافع وابن عامر وحمزة، وبمعنى البخيل", "عاصم وحمزة، وبمعنى المتَّهم بالكذب", "ابن عامر والكسائي، وبمعنى الغائب"], "قرأ ابن كثير وأبو عمرو والكسائي بالظاء ومعناه متَّهم، فليس النبي ﷺ متهمًا في أمر الغيب، وقرأ الباقون بالضاد ومعناه بخيل، فهو لا يكتم ما أُوحي إليه. والقراءتان متفقتان في تبرئة النبي ﷺ."] },

  { id: "xqr-023", s: "qiraat", g: 4, d: 6, t: ["conditions", "ibn-al-jazari"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, introduction; Ibn al-Jazarī, Ṭayyibat al-Nashr",
    en: ["Which three conditions did Ibn al-Jazarī lay down for a reading to be accepted?", ["Agreement with Arabic grammar in some way, agreement with one of the Uthmānic copies, and a sound chain of transmission", "Agreement with the dialect of Quraysh, with the first copy and with the majority of readers", "A chain of ten transmitters, agreement with Arabic poetry, and acceptance by a ruler", "Agreement with the rules of tajwīd, a famous reader, and written authorisation (ijāza)"], "In his poem he states that every reading that agrees with Arabic in any way, agrees with one of the copies, even by probability, and has a sound chain is a true reading. If one of the three is missing, the reading is shādhdh, weak or invalid. The conditions were set in contrast to those who demanded tawātur only."],
    de: ["Welche drei Bedingungen stellte Ibn al-Ǧazarī für die Annahme einer Lesart auf?", ["Übereinstimmung mit der arabischen Grammatik in irgendeiner Weise, Übereinstimmung mit einem der uṯmānischen Exemplare und eine gesunde Überliefererkette", "Übereinstimmung mit dem Dialekt der Quraiš, mit dem ersten Exemplar und mit der Mehrheit der Leser", "Eine Kette von zehn Überlieferern, Übereinstimmung mit arabischer Dichtung und Anerkennung durch einen Herrscher", "Übereinstimmung mit den Regeln des Tağwīd, ein berühmter Leser und eine schriftliche Erlaubnis (Iǧāza)"], "In seinem Gedicht legt er fest, jede Lesart, die in irgendeiner Weise mit dem Arabischen übereinstimmt, mit einem der Exemplare übereinstimmt, auch nur wahrscheinlich, und eine gesunde Kette hat, sei eine wahre Lesart. Fehlt eine der drei, ist die Lesart šāḏḏ, schwach oder ungültig. Die Bedingungen wurden im Gegensatz zu denen gesetzt, die nur Tawātur verlangten."],
    ar: ["ما الشروط الثلاثة التي وضعها ابن الجزري لقبول القراءة؟", ["موافقة العربية ولو بوجه، وموافقة أحد المصاحف العثمانية ولو احتمالًا، وصحة الإسناد", "موافقة لهجة قريش والمصحف الأول وأكثر القراء", "سلسلة من عشرة رواة وموافقة الشعر العربي وإقرار الحاكم", "موافقة أحكام التجويد واشتهار القارئ والإجازة المكتوبة"], "قرر في منظومته أن كل قراءة وافقت العربية ولو بوجه ووافقت أحد المصاحف ولو احتمالًا وصح إسنادها فهي القراءة الصحيحة، فإن اختل ركن منها فهي شاذة أو ضعيفة أو باطلة. وقد وضع ذلك في مقابل من اشترط التواتر وحده."] },

  { id: "xqr-024", s: "qiraat", g: 4, d: 7, t: ["conditions", "tawatur"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, introduction; al-Suyūṭī, al-Itqān, ch. on the types of readings",
    en: ["Ibn al-Jazarī in al-Nashr discussed the view that tawātur is a condition for a reading. Which is his position?", ["He considered the sound chain, agreement with the muṣḥaf and with Arabic enough, and argued that requiring tawātur would exclude readings accepted by the whole community", "He required a tawātur of at least ten transmitters at every level", "He rejected all readings that are not tawātur, including some of the Ten", "He held that chains do not matter if the reading is eloquent"], "He remarked that the community had accepted readings whose chains were sound without being of the kind of tawātur some demanded, and that insisting on it would drop well-known readings. At the same time, he treated the Ten as being mutawātir. The topic remains one of the major debates of the Quranic sciences."],
    de: ["Ibn al-Ǧazarī erörterte in al-Našr die Ansicht, Tawātur sei Bedingung für eine Lesart. Welche ist seine Position?", ["Er hielt die gesunde Kette sowie Übereinstimmung mit dem Muṣḥaf und mit dem Arabischen für ausreichend und argumentierte, die Forderung nach Tawātur schlösse von der ganzen Gemeinschaft anerkannte Lesarten aus", "Er verlangte auf jeder Stufe einen Tawātur von mindestens zehn Überlieferern", "Er verwarf alle Lesarten, die nicht mutawātir sind, auch einige der Zehn", "Er meinte, Ketten spielten keine Rolle, wenn die Lesart beredt ist"], "Er bemerkte, die Gemeinschaft habe Lesarten mit gesunder Kette angenommen, die nicht den Tawātur hatten, den manche verlangten, und dass das Beharren darauf bekannte Lesarten ausschlösse. Zugleich behandelte er die Zehn als mutawātir. Das Thema bleibt eine der großen Debatten der Koranwissenschaften."],
    ar: ["ناقش ابن الجزري في «النشر» رأي من اشترط التواتر في القراءة. ما موقفه؟", ["رأى أن صحة السند وموافقة المصحف والعربية كافية، وأن اشتراط التواتر يُخرج قراءات تلقتها الأمة بالقبول", "اشترط تواترًا بعشرة رواة على الأقل في كل طبقة", "ردّ كل قراءة غير متواترة حتى بعض العشرة", "رأى أن الإسناد لا يهم إذا كانت القراءة فصيحة"], "ذكر أن الأمة قبلت قراءات صح سندها ولم يحصل لها التواتر الذي اشترطه بعضهم، وأن في اشتراطه إسقاط قراءات مشهورة، مع أنه عدّ العشر متواترة. ويبقى الموضوع من كبريات مسائل علوم القرآن."] },

  { id: "xqr-025", s: "qiraat", g: 4, d: 6, t: ["terminology", "riwaya-tariq"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, introduction; Ibn al-Jazarī, Munjid al-Muqriʾīn",
    en: ["In the terminology of the qurrāʾ, what is the difference between qirāʾa, riwāya, ṭarīq and wajh?", ["Qirāʾa is attributed to the imam, riwāya to his transmitter, ṭarīq to those who transmit from the transmitter, and wajh is an option within a way", "Qirāʾa is a single word, riwāya a verse, ṭarīq a chapter and wajh a juz’", "They are exact synonyms", "Qirāʾa is an oral reading, riwāya a written one, ṭarīq a reading aloud and wajh a silent one"], "Ibn al-Jazarī and later scholars say that what is attributed to an imam is his qirāʾa, what is attributed to a transmitter from the imam is a riwāya, what is attributed to a person after them is a ṭarīq, and the options of the reader inside a way are awjuh. For example, Ḥafṣ is a riwāya of ʿĀṣim’s qirāʾa."],
    de: ["Was ist in der Terminologie der Qurrāʾ der Unterschied zwischen Qirāʾa, Riwāya, Ṭarīq und Wağh?", ["Qirāʾa wird dem Imam zugeschrieben, Riwāya seinem Überlieferer, Ṭarīq denen, die vom Überlieferer überliefern, und Wağh ist eine Option innerhalb eines Weges", "Qirāʾa ist ein einzelnes Wort, Riwāya ein Vers, Ṭarīq ein Kapitel und Wağh ein Dschuz’", "Sie sind genaue Synonyme", "Qirāʾa ist eine mündliche Lesung, Riwāya eine schriftliche, Ṭarīq eine laute und Wağh eine stille"], "Ibn al-Ǧazarī und spätere Gelehrte sagen: Was einem Imam zugeschrieben wird, ist seine Qirāʾa, was einem Überlieferer von dem Imam zugeschrieben wird, eine Riwāya, was einer Person danach zugeschrieben wird, ein Ṭarīq, und die Optionen des Lesers innerhalb eines Weges sind Awǧuh. Zum Beispiel ist Ḥafṣ eine Riwāya der Qirāʾa ʿĀṣims."],
    ar: ["ما الفرق في اصطلاح القراء بين القراءة والرواية والطريق والوجه؟", ["القراءة ما نُسب إلى الإمام، والرواية ما نُسب إلى الراوي عنه، والطريق ما نُسب إلى من روى عن الراوي، والوجه خيار للقارئ داخل الطريق", "القراءة كلمة واحدة والرواية آية والطريق سورة والوجه جزء", "هي ألفاظ مترادفة تمامًا", "القراءة شفوية والرواية مكتوبة والطريق جهرية والوجه سرّية"], "قرر ابن الجزري ومن بعده أن ما نُسب إلى الإمام فهو قراءة، وما نُسب إلى الراوي عنه فرواية، وما نُسب إلى من بعدهم فطريق، وما يتخير فيه القارئ داخل الطريق فأوجه. فحفص مثلًا رواية عن قراءة عاصم."] },

  { id: "xqr-026", s: "qiraat", g: 4, d: 6, t: ["shadhdh", "four-after-ten"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, introduction; al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. on the readers",
    en: ["Which four readers are usually listed as the ‘four after the ten’, whose readings are treated as shādhdh?", ["Ibn Muḥayṣin, al-Yazīdī, al-Ḥasan al-Baṣrī and al-Aʿmash", "Ibn Mujāhid, Ibn Shannabūdh, al-Dānī and al-Shāṭibī", "Warsh, Qālūn, Ḥafṣ and Shuʿba", "Abū Jaʿfar, Yaʿqūb, Khalaf and al-Kisāʾī"], "The four are Muḥammad ibn ʿAbd al-Raḥmān ibn Muḥayṣin, Yaḥyā ibn al-Mubārak al-Yazīdī, al-Ḥasan al-Baṣrī and Sulaymān al-Aʿmash. Their readings are not recited in prayers but are collected for linguistic and exegetical use. The others in the options are transmitters, scholars, or members of the Ten."],
    de: ["Welche vier Leser werden üblicherweise als die ‚vier nach den Zehn‘ aufgeführt, deren Lesarten als šāḏḏ gelten?", ["Ibn Muḥaiṣin, al-Yazīdī, al-Ḥasan al-Baṣrī und al-Aʿmaš", "Ibn Muǧāhid, Ibn Šannabūḏ, ad-Dānī und aš-Šāṭibī", "Warš, Qālūn, Ḥafṣ und Šuʿba", "Abū Ǧaʿfar, Yaʿqūb, Ḫalaf und al-Kisāʾī"], "Die vier sind Muḥammad ibn ʿAbd ar-Raḥmān ibn Muḥaiṣin, Yaḥyā ibn al-Mubārak al-Yazīdī, al-Ḥasan al-Baṣrī und Sulaimān al-Aʿmaš. Ihre Lesarten werden nicht im Gebet rezitiert, sondern für sprachliche und exegetische Zwecke gesammelt. Die anderen in den Optionen sind Überlieferer, Gelehrte oder Mitglieder der Zehn."],
    ar: ["من الأربعة الذين يُعدّون بعد العشرة وتُعتبر قراءاتهم شاذة عادةً؟", ["ابن محيصن واليزيدي والحسن البصري والأعمش", "ابن مجاهد وابن شنبوذ والداني والشاطبي", "ورش وقالون وحفص وشعبة", "أبو جعفر ويعقوب وخلف والكسائي"], "هم محمد بن عبد الرحمن بن محيصن ويحيى بن المبارك اليزيدي والحسن البصري وسليمان الأعمش، ولا يُقرأ بقراءاتهم في الصلاة وإنما تُجمع لفوائد لغوية وتفسيرية، أما غيرهم في الخيارات الأخرى فرواة أو علماء أو من العشرة."] },

  { id: "xqr-027", s: "qiraat", g: 4, d: 7, t: ["riwaya", "khalaf"], src: "Ibn al-Jazarī, Ghāyat al-Nihāya fī Ṭabaqāt al-Qurrāʾ; al-Dhahabī, Maʿrifat al-Qurrāʾ al-Kibār",
    en: ["Khalaf ibn Hishām al-Bazzār (d. 229 AH) is counted among the Ten. What is distinctive about his status?", ["He is both a transmitter of Ḥamza and an independent imam with his own choice, as the tenth reader", "He is only the transmitter of Nāfiʿ", "He is the teacher of Ibn Mujāhid", "He is a transmitter of ʿĀṣim"], "Khalaf transmitted the reading of Ḥamza, and also made his own selection (ikhtiyār), which differs from Ḥamza in a limited number of places; this selection is called Khalaf al-ʿĀshir, the tenth. Care must be taken to distinguish the two Khalafs, since one (Khalaf ʿan Ḥamza) is a riwāya and the other a separate qirāʾa."],
    de: ["Ḫalaf ibn Hišām al-Bazzār (gest. 229 n. H.) zählt zu den Zehn. Was ist an seinem Status besonders?", ["Er ist sowohl Überlieferer Ḥamzas als auch ein eigenständiger Imam mit eigener Wahl, als der zehnte Leser", "Er ist nur Überlieferer Nāfiʿs", "Er ist der Lehrer Ibn Muǧāhids", "Er ist ein Überlieferer ʿĀṣims"], "Ḫalaf überlieferte die Lesart Ḥamzas und traf auch eine eigene Wahl (Iḫtiyār), die sich an einer begrenzten Zahl von Stellen von Ḥamza unterscheidet; diese Wahl heißt Ḫalaf al-ʿĀšir, der Zehnte. Man muss die beiden Ḫalaf unterscheiden, da der eine (Ḫalaf ʿan Ḥamza) eine Riwāya und der andere eine eigene Qirāʾa ist."],
    ar: ["يُعدّ خلف بن هشام البزار (ت 229هـ) من العشرة. ما الذي يتميز به وضعه؟", ["هو راوٍ عن حمزة وإمام مستقل له اختيار خاص وهو القارئ العاشر", "هو راوي نافع فقط", "هو شيخ ابن مجاهد", "هو راوٍ عن عاصم"], "روى خلف قراءة حمزة، وكان له اختيار خاص يخالف فيه حمزة في مواضع محدودة، ويسمى خلف العاشر، فينبغي التمييز بين خلف عن حمزة وهو رواية وخلف العاشر وهو قراءة مستقلة."] },

  { id: "xqr-028", s: "qiraat", g: 4, d: 7, t: ["isnad", "asim"], src: "al-Dhahabī, Maʿrifat al-Qurrāʾ al-Kibār, on ʿĀṣim; Ibn al-Jazarī, Ghāyat al-Nihāya",
    en: ["Through whom did the two transmitters of ʿĀṣim receive his reading, according to the standard account of the chains?", ["Ḥafṣ is traced through Abū ʿAbd al-Raḥmān al-Sulamī to ʿAlī, and Shuʿba through Zirr ibn Ḥubaysh to Ibn Masʿūd", "Ḥafṣ through Zirr to Ibn Masʿūd and Shuʿba through al-Sulamī to ʿAlī", "Both through Nāfiʿ to Ubayy", "Both through Ibn ʿAbbās to the Prophet directly"], "ʿĀṣim ibn Abī al-Najūd studied with two teachers: Abū ʿAbd al-Raḥmān al-Sulamī, who read to ʿAlī (and ʿUthmān), and Zirr ibn Ḥubaysh, who read to Ibn Masʿūd. Ḥafṣ is said to have reported mostly the line of al-Sulamī and ʿAlī, while Shuʿba reported the line of Zirr and Ibn Masʿūd. All lines go back to the Prophet."],
    de: ["Über wen erhielten die beiden Überlieferer ʿĀṣims seine Lesart nach der üblichen Darstellung der Ketten?", ["Ḥafṣ wird über Abū ʿAbd ar-Raḥmān as-Sulamī auf ʿAlī zurückgeführt und Šuʿba über Zirr ibn Ḥubaiš auf Ibn Masʿūd", "Ḥafṣ über Zirr auf Ibn Masʿūd und Šuʿba über as-Sulamī auf ʿAlī", "Beide über Nāfiʿ auf Ubaiy", "Beide über Ibn ʿAbbās unmittelbar auf den Propheten"], "ʿĀṣim ibn Abī n-Naǧūd studierte bei zwei Lehrern: Abū ʿAbd ar-Raḥmān as-Sulamī, der bei ʿAlī (und ʿUṯmān) las, und Zirr ibn Ḥubaiš, der bei Ibn Masʿūd las. Von Ḥafṣ heißt es, er habe überwiegend die Linie as-Sulamīs und ʿAlīs überliefert, von Šuʿba die Linie Zirrs und Ibn Masʿūds. Alle Linien reichen bis zum Propheten."],
    ar: ["عن طريق من تلقى راويا عاصم قراءته على الرواية المشهورة في الأسانيد؟", ["حفص عن أبي عبد الرحمن السلمي عن علي، وشعبة عن زر بن حبيش عن ابن مسعود", "حفص عن زر عن ابن مسعود، وشعبة عن السلمي عن علي", "كلاهما عن نافع عن أُبيّ", "كلاهما عن ابن عباس عن النبي ﷺ مباشرة"], "قرأ عاصم بن أبي النجود على شيخين: أبي عبد الرحمن السلمي الذي قرأ على علي وعثمان، وزر بن حبيش الذي قرأ على ابن مسعود. ويُقال إن حفصًا أخذ غالبًا طريق السلمي عن علي وشعبة طريق زر عن ابن مسعود، وكلها تنتهي إلى النبي ﷺ."] },

  { id: "xqr-029", s: "qiraat", g: 4, d: 6, t: ["riwaya", "nafi"], src: "Ibn al-Jazarī, Ghāyat al-Nihāya fī Ṭabaqāt al-Qurrāʾ; al-Dānī, al-Taysīr",
    en: ["Which pair are the two classical transmitters of Nāfiʿ, whose riwāyas are used mostly in North and West Africa?", ["Qālūn and Warsh", "Al-Bazzī and Qunbul", "Hishām and Ibn Dhakwān", "Al-Dūrī and al-Sūsī"], "Qālūn (ʿĪsā ibn Mīnā) and Warsh (ʿUthmān ibn Saʿīd) transmitted Nāfiʿ’s reading of Madīna, and Warsh’s riwāya is widespread in the Maghrib, Sudan and West Africa. Al-Bazzī and Qunbul transmitted Ibn Kathīr, Hishām and Ibn Dhakwān Ibn ʿĀmir, and al-Dūrī and al-Sūsī Abū ʿAmr."],
    de: ["Welches Paar sind die beiden klassischen Überlieferer Nāfiʿs, deren Riwāyas vor allem in Nord- und Westafrika verwendet werden?", ["Qālūn und Warš", "Al-Bazzī und Qunbul", "Hišām und Ibn Ḏakwān", "Ad-Dūrī und as-Sūsī"], "Qālūn (ʿĪsā ibn Mīnā) und Warš (ʿUṯmān ibn Saʿīd) überlieferten Nāfiʿs Lesart von Medina, und Warš’ Riwāya ist im Maghreb, Sudan und Westafrika verbreitet. Al-Bazzī und Qunbul überlieferten Ibn Kaṯīr, Hišām und Ibn Ḏakwān Ibn ʿĀmir, und ad-Dūrī und as-Sūsī Abū ʿAmr."],
    ar: ["من الراويان المشهوران لنافع اللذان تُستعمل روايتاهما غالبًا في شمال إفريقيا وغربها؟", ["قالون وورش", "البزي وقنبل", "هشام وابن ذكوان", "الدوري والسوسي"], "روى قراءة نافع المدني قالون (عيسى بن مينا) وورش (عثمان بن سعيد)، ورواية ورش منتشرة في المغرب والسودان وغرب إفريقيا، أما البزي وقنبل فعن ابن كثير، وهشام وابن ذكوان عن ابن عامر، والدوري والسوسي عن أبي عمرو."] },

  { id: "xqr-030", s: "qiraat", g: 4, d: 6, t: ["classical-works", "ibn-mujahid"], src: "Ibn Mujāhid, Kitāb al-Sabʿa fī al-Qirāʾāt; Ibn al-Jazarī, al-Nashr, introduction",
    en: ["Which statement correctly describes Ibn Mujāhid’s Kitāb al-Sabʿa and its reception?", ["He chose seven imams of the main cities, and the selection later led some people to confuse the seven readings with the seven aḥruf, which scholars such as Ibn al-Jazarī corrected", "He wrote it to prove that the Quran has exactly seven aḥruf in the form of the seven readers", "He chose ten readers and excluded the Basrans", "He wrote it after the work of al-Shāṭibī"], "Ibn Mujāhid (d. 324 AH) selected seven well-known imams of the major cities in his Kitāb al-Sabʿa. Because the number was the same as that of the aḥruf in the hadith, some thought they were the same. Scholars point out that the aḥruf are not the readers: other competent readers existed, and later scholars added three more to the seven."],
    de: ["Welche Aussage beschreibt Ibn Muǧāhids Kitāb as-Sabʿa und seine Aufnahme richtig?", ["Er wählte sieben Imame der Hauptstädte aus, und die Auswahl führte später dazu, dass manche die sieben Lesarten mit den sieben Aḥruf verwechselten, was Gelehrte wie Ibn al-Ǧazarī richtigstellten", "Er schrieb es, um zu beweisen, dass der Koran genau sieben Aḥruf in Gestalt der sieben Leser hat", "Er wählte zehn Leser und schloss die Basrer aus", "Er schrieb es nach dem Werk von aš-Šāṭibī"], "Ibn Muǧāhid (gest. 324 n. H.) wählte in seinem Kitāb as-Sabʿa sieben bekannte Imame der großen Städte aus. Da die Zahl der der Aḥruf im Hadith entsprach, hielten manche beides für dasselbe. Die Gelehrten weisen darauf hin, dass die Aḥruf nicht die Leser sind: Es gab andere tüchtige Leser, und spätere Gelehrte fügten den Sieben drei weitere hinzu."],
    ar: ["أي عبارة تصف على الوجه الصحيح كتاب «السبعة» لابن مجاهد وأثره؟", ["اختار فيه سبعة أئمة من الأمصار الكبرى، فاختلط على بعض الناس أمر القراءات السبع بالأحرف السبعة وصحّح ذلك علماء كابن الجزري", "ألّفه ليثبت أن للقرآن سبعة أحرف بعدد القراء السبعة", "اختار عشرة قراء واستبعد أهل البصرة", "ألّفه بعد منظومة الشاطبي"], "اختار ابن مجاهد (ت 324هـ) في كتابه سبعة من أئمة القراءة في الأمصار الكبرى، ولما وافق العدد عدد الأحرف في الحديث ظنّ بعض الناس أنهما شيء واحد، وبيّن العلماء أن الأحرف ليست القراء، فقد كان غير السبعة من القراء الثقات، وأضاف المتأخرون ثلاثة إلى السبعة."] },

  { id: "xqr-031", s: "qiraat", g: 4, d: 6, t: ["classical-works", "shatibi"], src: "al-Shāṭibī, Ḥirz al-Amānī wa-Wajh al-Tahānī; al-Dānī, al-Taysīr fī al-Qirāʾāt al-Sabʿ",
    en: ["Which statement correctly describes the relationship between al-Shāṭibiyya and al-Taysīr?", ["The Shāṭibiyya (Ḥirz al-Amānī) is a poem that versifies al-Dānī’s al-Taysīr, with additions, on the Seven readings", "The Shāṭibiyya is a prose commentary on the Muqniʿ of al-Dānī", "The Taysīr versifies the Shāṭibiyya", "The two works treat different readings, the Seven and the Ten"], "Al-Shāṭibī (d. 590 AH) condensed al-Dānī’s al-Taysīr into a poem of about 1,170 verses, using letter codes for the readers. It became the main text for studying the Seven, while the Ten are covered by Ibn al-Jazarī’s al-Nashr and the poems al-Durra and al-Ṭayyiba."],
    de: ["Welche Aussage beschreibt das Verhältnis zwischen aš-Šāṭibiyya und at-Taysīr richtig?", ["Die Šāṭibiyya (Ḥirz al-Amānī) ist ein Gedicht, das ad-Dānīs at-Taysīr über die Sieben Lesarten mit Ergänzungen in Verse fasst", "Die Šāṭibiyya ist ein Prosakommentar zum Muqniʿ von ad-Dānī", "At-Taysīr versifiziert die Šāṭibiyya", "Die beiden Werke behandeln verschiedene Lesarten, die Sieben und die Zehn"], "Aš-Šāṭibī (gest. 590 n. H.) verdichtete ad-Dānīs at-Taysīr zu einem Gedicht von rund 1170 Versen mit Buchstabenkürzeln für die Leser. Es wurde zum Haupttext für das Studium der Sieben, während die Zehn durch Ibn al-Ǧazarīs an-Našr und die Gedichte ad-Durra und aṭ-Ṭayyiba abgedeckt werden."],
    ar: ["أي عبارة تصف العلاقة الصحيحة بين الشاطبية والتيسير؟", ["الشاطبية (حرز الأماني) منظومة تنظم «التيسير» للداني في القراءات السبع مع زيادات", "الشاطبية شرح نثري لـ«المقنع» للداني", "التيسير ينظم الشاطبية", "الكتابان في قراءات مختلفة: السبع والعشر"], "اختصر الشاطبي (ت 590هـ) التيسير للداني في نحو 1170 بيتًا واستعمل رموزًا حرفية للقراء، فصارت المتن الأول لدراسة السبعة، أما العشرة ففي «النشر» لابن الجزري ومنظومتي الدرة والطيبة."] },

  { id: "xqr-032", s: "qiraat", g: 4, d: 7, t: ["classical-works", "ibn-al-jazari"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr; Ibn al-Jazarī, al-Durra al-Muḍiyya; Ibn al-Jazarī, Ṭayyibat al-Nashr",
    en: ["Which statement correctly describes the relationship of Ibn al-Jazarī’s works to the Shāṭibiyya?", ["Al-Durra al-Muḍiyya completes the Seven of the Shāṭibiyya with the three readings of Abū Jaʿfar, Yaʿqūb and Khalaf, and Ṭayyibat al-Nashr versifies al-Nashr for all ten", "Al-Durra replaces the Shāṭibiyya for the Seven, and al-Ṭayyiba contains only the Seven", "Both works treat only shādhdh readings", "Al-Nashr is a poem and al-Ṭayyiba a prose work"], "Ibn al-Jazarī (d. 833 AH) wrote al-Durra al-Muḍiyya fī al-Qirāʾāt al-Thalātha al-Marḍiyya as a supplement to the Shāṭibiyya, adding Abū Jaʿfar, Yaʿqūb and Khalaf. Ṭayyibat al-Nashr is a poem of about 1,014 verses that versifies al-Nashr for the ten readings, and al-Nashr itself is the large prose work."],
    de: ["Welche Aussage beschreibt das Verhältnis der Werke Ibn al-Ǧazarīs zur Šāṭibiyya richtig?", ["Ad-Durra al-Muḍiyya ergänzt die Sieben der Šāṭibiyya um die drei Lesarten von Abū Ǧaʿfar, Yaʿqūb und Ḫalaf, und Ṭayyibat an-Našr versifiziert an-Našr für alle zehn", "Ad-Durra ersetzt die Šāṭibiyya für die Sieben, und aṭ-Ṭayyiba enthält nur die Sieben", "Beide Werke behandeln nur šāḏḏ-Lesarten", "An-Našr ist ein Gedicht und aṭ-Ṭayyiba ein Prosawerk"], "Ibn al-Ǧazarī (gest. 833 n. H.) schrieb ad-Durra al-Muḍiyya fī l-Qirāʾāt aṯ-Ṯalāṯa al-Marḍiyya als Ergänzung zur Šāṭibiyya und fügte Abū Ǧaʿfar, Yaʿqūb und Ḫalaf hinzu. Ṭayyibat an-Našr ist ein Gedicht von rund 1014 Versen, das an-Našr für die zehn Lesarten versifiziert, und an-Našr selbst ist das große Prosawerk."],
    ar: ["أي عبارة تصف علاقة كتب ابن الجزري بالشاطبية على الوجه الصحيح؟", ["الدرة المضية تكمل السبع بقراءات أبي جعفر ويعقوب وخلف، وطيبة النشر تنظم «النشر» للعشرة كلهم", "الدرة تحل محل الشاطبية في السبع والطيبة فيها السبع فقط", "الكتابان في القراءات الشاذة وحدها", "«النشر» منظومة و«الطيبة» نثر"], "ألّف ابن الجزري (ت 833هـ) «الدرة المضية في القراءات الثلاث المرضية» تتمةً للشاطبية فأضاف أبا جعفر ويعقوب وخلفًا، و«طيبة النشر» منظومة نحو 1014 بيتًا تنظم «النشر» في القراءات العشر، أما «النشر» نفسه فهو الأصل النثري الكبير."] },

  { id: "xqr-033", s: "qiraat", g: 4, d: 6, t: ["classical-works", "tawjih"], src: "Abū ʿAlī al-Fārisī, al-Ḥujja li-l-Qurrāʾ al-Sabʿa; Ibn Khālawayh, al-Ḥujja fī al-Qirāʾāt al-Sabʿ",
    en: ["Which work by Abū ʿAlī al-Fārisī is a major classical book of tawjīh, explaining the grammatical grounds of the Seven’s readings?", ["al-Ḥujja li-l-Qurrāʾ al-Sabʿa", "al-Nashr fī al-Qirāʾāt al-ʿAshr", "al-Taysīr", "al-Muqniʿ"], "Al-Ḥujja li-l-Qurrāʾ al-Sabʿa by Abū ʿAlī al-Fārisī (d. 377 AH) argues for the readings of the Seven by grammar and usage. Ibn Khālawayh wrote a work with a similar title; Makkī’s al-Kashf is another standard source. Al-Nashr is a collection of chains, al-Taysīr a transmission manual, and al-Muqniʿ a book on the rasm."],
    de: ["Welches Werk Abū ʿAlī al-Fārisīs ist ein großes klassisches Buch des Tawǧīh, das die grammatischen Gründe der Lesarten der Sieben erklärt?", ["Al-Ḥuǧǧa li-l-Qurrāʾ as-Sabʿa", "An-Našr fī l-Qirāʾāt al-ʿAšr", "At-Taysīr", "Al-Muqniʿ"], "Al-Ḥuǧǧa li-l-Qurrāʾ as-Sabʿa von Abū ʿAlī al-Fārisī (gest. 377 n. H.) begründet die Lesarten der Sieben durch Grammatik und Sprachgebrauch. Ibn Ḫālawaih schrieb ein Werk mit ähnlichem Titel; Makkīs al-Kašf ist eine weitere Standardquelle. An-Našr ist eine Sammlung von Ketten, at-Taysīr ein Überlieferungshandbuch und al-Muqniʿ ein Buch über den Rasm."],
    ar: ["أي كتاب لأبي علي الفارسي من أهم كتب التوجيه التي تعلّل قراءات السبعة نحويًّا؟", ["الحجة للقراء السبعة", "النشر في القراءات العشر", "التيسير", "المقنع"], "«الحجة للقراء السبعة» لأبي علي الفارسي (ت 377هـ) يحتج لقراءات السبعة بالنحو والاستعمال، وألّف ابن خالويه كتابًا بعنوان مشابه، ويعدّ «الكشف» لمكي مصدرًا معياريًّا آخر. أما «النشر» فجامع للأسانيد و«التيسير» دليل رواية و«المقنع» في الرسم."] },

  { id: "xqr-034", s: "qiraat", g: 4, d: 7, t: ["ahruf-and-qiraat", "terminology"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on the seven aḥruf; al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān; Abū Shāma, al-Murshid al-Wajīz",
    en: ["Which statement correctly states the relation between the seven aḥruf of the hadith and the Seven readings?", ["Scholars distinguish them: the seven aḥruf are the permitted aspects of difference in the revelation, whereas the Seven are a later selection by Ibn Mujāhid", "They are identical and each reader corresponds to one ḥarf", "The Seven are the seven aḥruf recited by seven Companions", "There is no relation, because the aḥruf were abolished by the Prophet"], "Ibn al-Jazarī and many others, including Abū Shāma, warn against equating the two, because the number of the aḥruf in the hadith is older than the selection of Ibn Mujāhid and the Seven readings do not correspond to the aḥruf one by one. The ʿUthmānic copies kept what was established in the final recitation, which the readings reflect."],
    de: ["Welche Aussage gibt das Verhältnis zwischen den sieben Aḥruf des Hadith und den Sieben Lesarten richtig wieder?", ["Die Gelehrten unterscheiden sie: Die sieben Aḥruf sind die erlaubten Aspekte der Verschiedenheit in der Offenbarung, die Sieben dagegen eine spätere Auswahl Ibn Muǧāhids", "Sie sind identisch, und jeder Leser entspricht einem Ḥarf", "Die Sieben sind die sieben Aḥruf, von sieben Gefährten rezitiert", "Es besteht kein Zusammenhang, weil die Aḥruf vom Propheten aufgehoben wurden"], "Ibn al-Ǧazarī und viele andere, darunter Abū Šāma, warnen davor, beides gleichzusetzen, weil die Zahl der Aḥruf im Hadith älter ist als die Auswahl Ibn Muǧāhids und die Sieben Lesarten den Aḥruf nicht eins zu eins entsprechen. Die uṯmānischen Exemplare bewahrten, was bei der letzten Rezitation feststand, was die Lesarten widerspiegeln."],
    ar: ["أي عبارة تبيّن العلاقة الصحيحة بين الأحرف السبعة في الحديث والقراءات السبع؟", ["يفرّق العلماء بينهما: الأحرف السبعة وجوه الاختلاف المأذون بها في الوحي، أما القراءات السبع فاختيار متأخر لابن مجاهد", "هما شيء واحد ولكل قارئ حرف", "القراءات السبع هي الأحرف السبعة قرأ بها سبعة من الصحابة", "لا علاقة لأن النبي ﷺ ألغى الأحرف"], "حذّر ابن الجزري وغيره كأبي شامة من التسوية بينهما لأن عدد الأحرف في الحديث أقدم من اختيار ابن مجاهد، ولا تقابل القراءات السبع الأحرف السبعة واحدًا بواحد، وقد أبقت المصاحف العثمانية ما ثبت في العرضة الأخيرة وهو ما تعبّر عنه القراءات."] },

  { id: "xqr-035", s: "qiraat", g: 4, d: 7, t: ["classification", "types-of-readings"], src: "al-Suyūṭī, al-Itqān fī ʿUlūm al-Qurʾān, ch. 22 on the types of readings",
    en: ["Which six categories of readings does al-Suyūṭī list in al-Itqān, in order from the strongest to the weakest?", ["Mutawātir, mashhūr, āḥād, shādhdh, mawḍūʿ and mudraj", "Ṣaḥīḥ, ḥasan, ḍaʿīf, munkar, mawḍūʿ and mudraj", "Mutawātir, ṣaḥīḥ, ḥasan, marfūʿ, mawqūf and maqṭūʿ", "Mashhūr, ṣaḥīḥ, ḥasan, ḍaʿīf, mursal and mudallas"], "Al-Suyūṭī, following Ibn al-Jazarī’s and earlier analysis, divides the readings into six: mutawātir (the Ten), mashhūr, āḥād (sound chain but contrary to the rasm or Arabic), shādhdh, mawḍūʿ (fabricated) and mudraj (explanatory additions inserted). The terms are borrowed from hadith but adapted to readings."],
    de: ["Welche sechs Kategorien von Lesarten führt as-Suyūṭī in al-Itqān auf, von der stärksten zur schwächsten?", ["Mutawātir, mašhūr, āḥād, šāḏḏ, mawḍūʿ und mudraǧ", "Ṣaḥīḥ, ḥasan, ḍaʿīf, munkar, mawḍūʿ und mudraǧ", "Mutawātir, ṣaḥīḥ, ḥasan, marfūʿ, mawqūf und maqṭūʿ", "Mašhūr, ṣaḥīḥ, ḥasan, ḍaʿīf, mursal und mudallas"], "As-Suyūṭī teilt in Anlehnung an Ibn al-Ǧazarī und frühere Analysen die Lesarten in sechs: mutawātir (die Zehn), mašhūr, āḥād (gesunde Kette, aber gegen den Rasm oder das Arabische), šāḏḏ, mawḍūʿ (erfunden) und mudraǧ (eingefügte erläuternde Zusätze). Die Begriffe sind dem Hadith entlehnt, aber auf Lesarten angepasst."],
    ar: ["ما الأنواع الستة للقراءات التي يذكرها السيوطي في «الإتقان» مرتبة من الأقوى إلى الأضعف؟", ["المتواتر والمشهور والآحاد والشاذ والموضوع والمدرج", "الصحيح والحسن والضعيف والمنكر والموضوع والمدرج", "المتواتر والصحيح والحسن والمرفوع والموقوف والمقطوع", "المشهور والصحيح والحسن والضعيف والمرسل والمدلس"], "قسّم السيوطي القراءات إلى ستة أنواع متابعًا ابن الجزري ومن قبله: المتواتر (العشر) ثم المشهور ثم الآحاد (صح سنده وخالف الرسم أو العربية) ثم الشاذ ثم الموضوع (المختلق) ثم المدرج (ما زيد على وجه التفسير). والألفاظ مستعارة من الحديث مع تكييفها للقراءات."] },

  { id: "xqr-036", s: "qiraat", g: 4, d: 6, t: ["riwaya", "hafs-spread"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, on the riwāyas in use; Mannāʿ al-Qaṭṭān, Mabāḥith fī ʿUlūm al-Qurʾān",
    en: ["Which statement fairly explains why the riwāya of Ḥafṣ ʿan ʿĀṣim is today the most widespread in the Muslim world?", ["Historical reasons, such as its adoption in the lands of the Ottoman state and in printed muṣḥafs, rather than any scholarly ranking of readings above others", "It is the only reading that is mutawātir", "The Prophet preferred it to all others", "It was the only reading authorised by the Uthmānic copies"], "The wide use of Ḥafṣ is explained historically: it was the reading favoured in the Ottoman and later Eastern world and became standard in printing. Scholars do not rank it above the other mutawātir readings, all of which are valid. Today other riwāyas, such as Warsh and Qālūn, continue in North and West Africa."],
    de: ["Welche Aussage erklärt zutreffend, warum die Riwāya von Ḥafṣ ʿan ʿĀṣim heute in der muslimischen Welt am weitesten verbreitet ist?", ["Historische Gründe, etwa ihre Übernahme in den Ländern des osmanischen Staates und in gedruckten Muṣḥafen, nicht ein gelehrter Vorrang vor anderen Lesarten", "Sie ist die einzige Lesart, die mutawātir ist", "Der Prophet zog sie allen anderen vor", "Sie war die einzige Lesart, die von den uṯmānischen Exemplaren gedeckt war"], "Die weite Verbreitung von Ḥafṣ wird historisch erklärt: Sie war die bevorzugte Lesart im osmanischen und späteren östlichen Raum und wurde im Druck zum Standard. Die Gelehrten stellen sie nicht über die anderen mutawātir-Lesarten, die alle gültig sind. Heute bestehen andere Riwāyas wie Warš und Qālūn in Nord- und Westafrika fort."],
    ar: ["أي عبارة تفسّر على الوجه المنصف انتشار رواية حفص عن عاصم اليوم في العالم الإسلامي؟", ["أسباب تاريخية كاعتمادها في بلاد الدولة العثمانية وفي طباعة المصاحف، لا تفضيل علمي لها على غيرها من القراءات", "هي القراءة المتواترة الوحيدة", "فضّلها النبي ﷺ على غيرها", "هي القراءة الوحيدة التي تحتملها المصاحف العثمانية"], "يُفسَّر شيوع حفص تاريخيًّا بأنه القراءة المفضلة في الشرق العثماني ثم غلبت على الطباعة، ولا يفضّله العلماء على سائر القراءات المتواترة وكلها صحيحة. وما زالت روايات أخرى كورش وقالون قائمة في شمال إفريقيا وغربها."] },

  { id: "xqr-037", s: "qiraat", g: 4, d: 7, t: ["terminology", "ikhtilaf"], src: "Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, ch. on the benefits of the differences in readings; al-Zarkashī, al-Burhān fī ʿUlūm al-Qurʾān",
    en: ["How do the classical scholars of qirāʾāt, such as Ibn al-Jazarī, describe the nature of the differences between the accepted readings?", ["As a difference of variety and diversity (ikhtilāf tanawwuʿ), not of contradiction, where each reading adds a meaning or a facility", "As a difference of contradiction in which only one reading can be true", "As a difference only in pronunciation that never touches meaning", "As a difference that the community resolved by abolishing all but one"], "Ibn al-Jazarī and others stress that the accepted differences are not contradictory: each reading either adds a meaning (as in the verse of the feet) or gives a facility to the nations’ dialects, and the readings together are like different verses. This is why jurists and commentators may use one reading to explain another."],
    de: ["Wie beschreiben die klassischen Gelehrten der Qirāʾāt wie Ibn al-Ǧazarī die Natur der Unterschiede zwischen den anerkannten Lesarten?", ["Als Unterschied der Vielfalt (iḫtilāf tanawwuʿ), nicht des Widerspruchs, wobei jede Lesart eine Bedeutung oder eine Erleichterung hinzufügt", "Als Unterschied des Widerspruchs, bei dem nur eine Lesart wahr sein kann", "Als Unterschied nur in der Aussprache, der den Sinn nie berührt", "Als Unterschied, den die Gemeinschaft löste, indem sie alle bis auf eine abschaffte"], "Ibn al-Ǧazarī und andere betonen, dass die anerkannten Unterschiede nicht widersprüchlich sind: Jede Lesart fügt entweder eine Bedeutung hinzu (wie im Vers von den Füßen) oder bietet den Mundarten der Völker eine Erleichterung, und die Lesarten zusammen sind wie verschiedene Verse. Deshalb dürfen Juristen und Kommentatoren eine Lesart zur Erklärung einer anderen heranziehen."],
    ar: ["كيف يصف علماء القراءات القدماء كابن الجزري طبيعة الاختلاف بين القراءات المقبولة؟", ["اختلاف تنوع وتغاير لا تضاد وتناقض، تزيد كل قراءة معنى أو تيسيرًا", "اختلاف تضاد لا تصح فيه إلا قراءة واحدة", "اختلاف في النطق وحده لا يمس المعنى أبدًا", "اختلاف حسمته الأمة بإلغاء كل القراءات إلا واحدة"], "يؤكد ابن الجزري وغيره أن الاختلاف المقبول لا تضاد فيه: فكل قراءة إما تزيد معنى (كما في آية الوضوء) وإما تيسّر على لغات الأمم، وهي بمنزلة الآيات المتعددة، ولذلك جاز للفقهاء والمفسرين أن يفسروا قراءة بأخرى."] },

  { id: "xqr-038", s: "qiraat", g: 4, d: 6, t: ["usul", "sakt-hamza"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb al-sakt ʿalā al-sākin qabl al-hamz; al-Dānī, al-Taysīr",
    en: ["Which reader of the Seven is known for making a sakta on the sākin letter before a hamza (for example on the lām of the article before a hamza)?", ["Ḥamza", "Ḥafṣ", "Ibn ʿĀmir", "Abū ʿAmr"], "Ḥamza makes a sakta in continuation on a sākin letter before a hamza, a famous feature of his reading, as on the lām of the article before a hamza in the same word and in separate words, and on a few words such as ‘shayʾ’. Ḥafṣ makes a sakta only in four places. Warsh has a similar feature in a different form."],
    de: ["Welcher der Sieben ist dafür bekannt, eine Sakta auf dem Sākin-Buchstaben vor einem Hamza zu machen (zum Beispiel auf dem Lām des Artikels vor einem Hamza)?", ["Ḥamza", "Ḥafṣ", "Ibn ʿĀmir", "Abū ʿAmr"], "Ḥamza macht beim Weiterlesen eine Sakta auf einem Sākin-Buchstaben vor einem Hamza, ein berühmtes Merkmal seiner Lesart, etwa auf dem Lām des Artikels vor einem Hamza im selben Wort und in getrennten Wörtern sowie bei wenigen Wörtern wie ‚šaiʾ‘. Ḥafṣ macht eine Sakta nur an vier Stellen. Warš hat ein ähnliches Merkmal in anderer Form."],
    ar: ["أي قارئ من السبعة اشتهر بالسكت على الحرف الساكن قبل الهمزة، كالسكت على لام التعريف قبل الهمزة؟", ["حمزة", "حفص", "ابن عامر", "أبو عمرو"], "اشتهر حمزة بالسكت وصلًا على الساكن قبل الهمز، كلام التعريف قبل الهمزة في كلمة وفي كلمتين وبعض الكلمات مثل لفظ الشيء، أما حفص فلا يسكت إلا في أربعة مواضع، ولورش ما يشبهه على وجه آخر."] },

  { id: "xqr-039", s: "qiraat", g: 4, d: 6, t: ["usul", "imala"], src: "al-Shāṭibī, Ḥirz al-Amānī, bāb al-fatḥ wa-l-imāla; Ibn al-Jazarī, al-Nashr, bāb al-imāla",
    en: ["Which of the Seven are best known for a wide use of imāla (inclining the fatḥa and alif toward kasra and yāʾ)?", ["Ḥamza and al-Kisāʾī", "Ibn Kathīr and Nāfiʿ", "Ibn ʿĀmir and Ḥafṣ", "ʿĀṣim and Ibn Kathīr"], "Ḥamza and al-Kisāʾī (and Khalaf) make imāla in many words, in a rule-based way, while Abū ʿAmr and others do so in selected words and Ibn Kathīr does not. Ḥafṣ makes only one imāla in the whole Quran (11:41)."],
    de: ["Welche der Sieben sind für einen weiten Gebrauch der Imāla (Neigung von Fatḥa und Alif zu Kasra und Yāʾ) bekannt?", ["Ḥamza und al-Kisāʾī", "Ibn Kaṯīr und Nāfiʿ", "Ibn ʿĀmir und Ḥafṣ", "ʿĀṣim und Ibn Kaṯīr"], "Ḥamza und al-Kisāʾī (und Ḫalaf) machen Imāla in vielen Wörtern, nach Regeln, während Abū ʿAmr und andere sie in ausgewählten Wörtern machen und Ibn Kaṯīr nicht. Ḥafṣ macht nur eine Imāla im ganzen Koran (11:41)."],
    ar: ["أي القراء السبعة اشتهروا بالتوسع في الإمالة (ميل الفتحة والألف نحو الكسرة والياء)؟", ["حمزة والكسائي", "ابن كثير ونافع", "ابن عامر وحفص", "عاصم وابن كثير"], "يميل حمزة والكسائي (وخلف) في كلمات كثيرة وفق قواعد مطردة، ويميل أبو عمرو وغيره في كلمات مخصوصة، ولا يميل ابن كثير، أما حفص فليس عنده إلا إمالة واحدة في القرآن كله (هود 41)."] },

  { id: "xqr-040", s: "qiraat", g: 4, d: 6, t: ["riwaya", "the-ten"], src: "Ibn al-Jazarī, Ghāyat al-Nihāya fī Ṭabaqāt al-Qurrāʾ; Ibn al-Jazarī, al-Durra al-Muḍiyya",
    en: ["Which transmitters are associated with the two readers Abū Jaʿfar and Yaʿqūb, respectively?", ["Abū Jaʿfar: Ibn Wardān and Ibn Jammāz; Yaʿqūb: Ruways and Rawḥ", "Abū Jaʿfar: Qālūn and Warsh; Yaʿqūb: Hishām and Ibn Dhakwān", "Abū Jaʿfar: Shuʿba and Ḥafṣ; Yaʿqūb: al-Bazzī and Qunbul", "Abū Jaʿfar: al-Dūrī and al-Sūsī; Yaʿqūb: Khalaf and Khallād"], "Abū Jaʿfar of Madīna is transmitted by ʿĪsā ibn Wardān and Sulaymān ibn Jammāz, and Yaʿqūb al-Ḥaḍramī of Baṣra by Ruways and Rawḥ. The other pairs belong to Nāfiʿ, Ibn ʿĀmir, ʿĀṣim, Ibn Kathīr, Abū ʿAmr and Ḥamza. These three readers complete the Seven to make the Ten in al-Durra."],
    de: ["Welche Überlieferer gehören zu den beiden Lesern Abū Ǧaʿfar bzw. Yaʿqūb?", ["Abū Ǧaʿfar: Ibn Wardān und Ibn Ǧammāz; Yaʿqūb: Ruwais und Rauḥ", "Abū Ǧaʿfar: Qālūn und Warš; Yaʿqūb: Hišām und Ibn Ḏakwān", "Abū Ǧaʿfar: Šuʿba und Ḥafṣ; Yaʿqūb: al-Bazzī und Qunbul", "Abū Ǧaʿfar: ad-Dūrī und as-Sūsī; Yaʿqūb: Ḫalaf und Ḫallād"], "Abū Ǧaʿfar von Medina wird von ʿĪsā ibn Wardān und Sulaimān ibn Ǧammāz überliefert, Yaʿqūb al-Ḥaḍramī von Basra von Ruwais und Rauḥ. Die anderen Paare gehören zu Nāfiʿ, Ibn ʿĀmir, ʿĀṣim, Ibn Kaṯīr, Abū ʿAmr und Ḥamza. Diese drei Leser ergänzen die Sieben zu den Zehn in ad-Durra."],
    ar: ["من راويا كل من القارئين أبي جعفر ويعقوب على الترتيب؟", ["أبو جعفر: ابن وردان وابن جماز؛ يعقوب: رويس وروح", "أبو جعفر: قالون وورش؛ يعقوب: هشام وابن ذكوان", "أبو جعفر: شعبة وحفص؛ يعقوب: البزي وقنبل", "أبو جعفر: الدوري والسوسي؛ يعقوب: خلف وخلاد"], "روى عن أبي جعفر المدني عيسى بن وردان وسليمان بن جماز، وعن يعقوب الحضرمي البصري رويس وروح، أما الأزواج الأخرى فلنافع وابن عامر وعاصم وابن كثير وأبي عمرو وحمزة، وهؤلاء الثلاثة يتممون السبعة عشرةً في الدرة."] },
];
